import type { Soru } from "../sorular";

export const P04: Soru[] = [
  { id: "p04-001", k: "Dünya", s: "Dünya atmosferinde hacimce en bol bulunan gaz hangisidir?", d: "Azot", y: ["Oksijen", "Karbondioksit"], a: "Kuru havanın yaklaşık %78'i azottur. Oksijen yaklaşık %21 ile ikinci sırada gelir." },
  { id: "p04-002", k: "Dünya", s: "Kuru havada oksijenin hacimce payı yaklaşık yüzde kaçtır?", d: "Yaklaşık %21", y: ["Yaklaşık %78", "Yaklaşık %50"], a: "Soluduğumuz havanın yaklaşık beşte biri oksijendir. Geri kalanın büyük kısmı azottur." },
  { id: "p04-003", k: "Dünya", s: "Kuru havada azot ve oksijenden sonra en bol bulunan gaz hangisidir?", d: "Argon", y: ["Karbondioksit", "Hidrojen"], a: "Argon kuru havanın yaklaşık %0,9'unu oluşturur. Karbondioksit ise yalnızca yaklaşık %0,04 kadardır." },
  { id: "p04-004", k: "Dünya", s: "Hava olaylarının büyük kısmı atmosferin hangi katmanında yaşanır?", d: "Troposfer", y: ["Stratosfer", "Mezosfer"], a: "Bulutların, yağışın ve fırtınaların neredeyse tamamı yere en yakın katman olan troposferde oluşur." },
  { id: "p04-005", k: "Dünya", s: "Ozon tabakası atmosferin hangi katmanında bulunur?", d: "Stratosfer", y: ["Troposfer", "Termosfer"], a: "Ozonun büyük kısmı stratosferde, yaklaşık 15-35 km yükseklikler arasında yoğunlaşır." },
  { id: "p04-006", k: "Dünya", s: "Stratosferde yükseldikçe sıcaklık neden artar?", d: "Ozon morötesi ışığı emdiği için", y: ["Yere daha yakın olduğu için", "Bulutlar ısıyı tuttuğu için"], a: "Ozon, Güneş'ten gelen morötesi ışınları emerek çevresini ısıtır. Bu yüzden stratosferde sıcaklık yukarı doğru artar." },
  { id: "p04-007", k: "Dünya", s: "Troposferde sıcaklık ortalama her kilometrede yaklaşık kaç derece düşer?", d: "Yaklaşık 6,5 °C", y: ["Yaklaşık 1 °C", "Yaklaşık 20 °C"], a: "Troposferde yükseldikçe hava soğur. Standart atmosferde bu düşüş kilometre başına yaklaşık 6,5 °C kabul edilir." },
  { id: "p04-008", k: "Dünya", s: "Troposfer ile stratosfer arasındaki sınıra ne ad verilir?", d: "Tropopoz", y: ["Stratopoz", "Mezopoz"], a: "Tropopoz, sıcaklığın yükseklikle düşmeyi bıraktığı sınırdır. Stratopoz ise stratosferin üst sınırıdır." },
  { id: "p04-009", k: "Dünya", s: "Troposfer en kalın hâlini nerede alır?", d: "Ekvator üzerinde", y: ["Kutuplar üzerinde", "Orta enlemlerde"], a: "Troposfer ekvatorda yaklaşık 16-18 km, kutuplarda ise yaklaşık 8 km kalınlığındadır. Sıcak hava daha yükseğe taşınır." },
  { id: "p04-010", k: "Dünya", s: "Atmosferin en soğuk katmanı hangisidir?", d: "Mezosfer", y: ["Stratosfer", "Termosfer"], a: "Mezosferin üst kısmında sıcaklık yaklaşık -90 °C'ye kadar iner. Burası atmosferin en soğuk bölgesidir." },
  { id: "p04-011", k: "Dünya", s: "Kayan yıldız olarak gördüğümüz göktaşlarının çoğu hangi katmanda yanar?", d: "Mezosfer", y: ["Troposfer", "Ekzosfer"], a: "Uzaydan gelen küçük taşlar mezosferde havayla sürtünüp ısınır ve çoğu burada yanarak yok olur." },
  { id: "p04-012", k: "Dünya", s: "Kutup ışıkları çoğunlukla atmosferin hangi katmanında oluşur?", d: "Termosfer", y: ["Troposfer", "Stratosfer"], a: "Kutup ışıkları genellikle 100 km'nin üzerinde, termosferde oluşur. Güneş'ten gelen parçacıklar buradaki gazları parlatır." },
  { id: "p04-013", k: "Dünya", s: "Uluslararası Uzay İstasyonu atmosferin hangi katmanı içinde dolanır?", d: "Termosfer", y: ["Mezosfer", "Stratosfer"], a: "İstasyon yaklaşık 400 km yükseklikte döner. Bu yükseklik, havanın son derece seyrek olduğu termosferin içinde kalır." },
  { id: "p04-014", k: "Dünya", s: "Atmosferin uzaya açılan en dış katmanı hangisidir?", d: "Ekzosfer", y: ["Termosfer", "Mezosfer"], a: "Ekzosfer, gaz atomlarının çok seyrek olduğu ve yavaş yavaş uzaya karıştığı en dış katmandır." },
  { id: "p04-015", k: "Dünya", s: "Radyo dalgalarını yansıtarak uzak mesafe iletişime yardım eden, iyonca zengin bölgeye ne denir?", d: "İyonosfer", y: ["Ozonosfer", "Tropopoz"], a: "İyonosfer, Güneş ışınımıyla iyonlaşmış gazlar içerir. Bazı radyo dalgalarını yansıtarak ufkun ötesine ulaştırır." },
  { id: "p04-016", k: "Dünya", s: "Bir ozon molekülü kaç oksijen atomundan oluşur?", d: "3", y: ["2", "4"], a: "Soluduğumuz oksijen iki atomludur. Ozon ise üç oksijen atomundan oluşur ve morötesi ışığı emer." },
  { id: "p04-017", k: "Dünya", s: "Antarktika üzerindeki ozon incelmesi yılın hangi döneminde en belirgin hâle gelir?", d: "Güney yarımküre ilkbaharında", y: ["Güney yarımküre yazında", "Güney yarımküre sonbaharında"], a: "Ozon deliği her yıl Ağustos-Ekim arasında, yani güney yarımkürenin ilkbaharında belirginleşir." },
  { id: "p04-018", k: "Dünya", s: "Ozon tabakasını incelten başlıca insan yapımı gazlar hangileridir?", d: "Kloroflorokarbonlar (CFC)", y: ["Su buharı ve argon", "Azot ve oksijen"], a: "Eski buzdolabı ve spreylerde kullanılan CFC'ler stratosferde klor salarak ozonu parçalar. Bu gazlar artık yasaklanmıştır." },
  { id: "p04-019", k: "Dünya", s: "Deniz seviyesinde standart hava basıncı yaklaşık kaç hektopaskaldır?", d: "1013 hPa", y: ["760 hPa", "500 hPa"], a: "Standart deniz seviyesi basıncı 1013,25 hPa'dır. 760 sayısı ise aynı basıncın milimetre cıva karşılığıdır." },
  { id: "p04-020", k: "Dünya", s: "Deniz seviyesindeki standart hava basıncı kaç milimetre cıva sütununa eşittir?", d: "760 mm", y: ["1013 mm", "100 mm"], a: "Torricelli'nin deneyinde hava basıncı cıvayı yaklaşık 760 mm yükseklikte tutar. Bu, 1 atmosfere karşılık gelir." },
  { id: "p04-021", k: "Dünya", s: "Hava basıncını ölçen alete ne ad verilir?", d: "Barometre", y: ["Higrometre", "Anemometre"], a: "Barometre hava basıncını ölçer. Basınçtaki değişimler havanın nasıl değişeceği hakkında ipucu verir." },
  { id: "p04-022", k: "Dünya", s: "Rüzgâr hızını ölçen alet hangisidir?", d: "Anemometre", y: ["Barometre", "Termometre"], a: "Anemometre çoğunlukla dönen kepçeleriyle rüzgârın hızını ölçer." },
  { id: "p04-023", k: "Dünya", s: "Havadaki nemi ölçen alete ne denir?", d: "Higrometre", y: ["Barometre", "Altimetre"], a: "Higrometre havadaki su buharı miktarını, çoğunlukla bağıl nem olarak ölçer." },
  { id: "p04-024", k: "Dünya", s: "Yağış miktarını ölçmek için kullanılan alet hangisidir?", d: "Plüviyometre", y: ["Higrometre", "Altimetre"], a: "Plüviyometre (yağmur ölçer), belli bir alana düşen yağışı milimetre cinsinden ölçer." },
  { id: "p04-025", k: "Dünya", s: "Yükseldikçe hava basıncı nasıl değişir?", d: "Azalır", y: ["Artar", "Değişmez"], a: "Yukarı çıktıkça üstümüzde kalan hava azalır. Bu yüzden basınç yükseklikle birlikte düşer." },
  { id: "p04-026", k: "Dünya", s: "Deniz seviyesinden yaklaşık 5,5 km yükseklikte hava basıncı, yerdekinin kabaca ne kadarıdır?", d: "Yarısı", y: ["İki katı", "Onda biri"], a: "Atmosferin kütlesinin yaklaşık yarısı 5,5 km'nin altındadır. Bu yükseklikte basınç yaklaşık 500 hPa'ya iner." },
  { id: "p04-027", k: "Dünya", s: "Atmosferin toplam kütlesinin yaklaşık ne kadarı troposferde bulunur?", d: "Dörtte üçünden fazlası", y: ["Yaklaşık onda biri", "Yaklaşık üçte biri"], a: "Troposfer ince bir katman olsa da atmosferdeki havanın yaklaşık %75-80'i burada toplanır." },
  { id: "p04-028", k: "Dünya", s: "Uzayın başlangıcı olarak sık kullanılan Kármán hattı yaklaşık kaç km yüksekliktedir?", d: "100 km", y: ["10 km", "1000 km"], a: "Kármán hattı deniz seviyesinden yaklaşık 100 km yükseklikte kabul edilir. Uluslararası kayıtlarda uzay sınırı olarak kullanılır." },
  { id: "p04-029", k: "Dünya", s: "Rüzgârın oluşmasının temel nedeni nedir?", d: "Basınç farkları", y: ["Dünya'nın manyetik alanı", "Ay'ın çekimi"], a: "Güneş yeryüzünü eşit ısıtmaz. Oluşan basınç farkları havayı bir yerden başka bir yere hareket ettirir." },
  { id: "p04-030", k: "Dünya", s: "Rüzgâr genel olarak hangi yönde eser?", d: "Yüksek basınçtan alçak basınca", y: ["Alçak basınçtan yüksek basınca", "Her zaman doğudan batıya"], a: "Hava, yoğun olduğu yüksek basınç alanından seyrek olduğu alçak basınç alanına doğru akar." },
  { id: "p04-031", k: "Dünya", s: "Kuzey yarımkürede alçak basınç merkezi çevresinde rüzgârlar hangi yönde döner?", d: "Saat yönünün tersine", y: ["Saat yönünde", "Hiç dönmez"], a: "Coriolis etkisi yüzünden kuzey yarımkürede alçak basınç sistemleri saat yönünün tersine döner." },
  { id: "p04-032", k: "Dünya", s: "Hareket eden hava ve su kütlelerini Dünya'nın dönüşü nedeniyle saptıran etkiye ne denir?", d: "Coriolis etkisi", y: ["Doppler etkisi", "Sera etkisi"], a: "Coriolis etkisi, Dünya döndüğü için hareket eden kütlelerin yolunu kuzey yarımkürede sağa, güneyde sola büker." },
  { id: "p04-033", k: "Dünya", s: "Coriolis etkisi kuzey yarımkürede rüzgârları hangi yöne saptırır?", d: "Sağa", y: ["Sola", "Yukarı"], a: "Kuzey yarımkürede hareket yönüne göre sağa, güney yarımkürede ise sola sapma görülür." },
  { id: "p04-034", k: "Dünya", s: "Ekvator ile yaklaşık 30° enlemleri arasında düzenli esen rüzgârlara ne denir?", d: "Alize rüzgârları", y: ["Batı rüzgârları", "Kutup rüzgârları"], a: "Alizeler, yelkenli gemilerin okyanusları geçmesinde yüzyıllarca önemli rol oynamıştır." },
  { id: "p04-035", k: "Dünya", s: "Alize rüzgârları kuzey yarımkürede genellikle hangi yönden eser?", d: "Kuzeydoğudan", y: ["Güneybatıdan", "Kuzeybatıdan"], a: "Ekvatora doğru akan hava Coriolis etkisiyle sağa sapar. Bu yüzden kuzey yarımküre alizeleri kuzeydoğudan eser." },
  { id: "p04-036", k: "Dünya", s: "Orta enlemlerde (yaklaşık 30-60°) hâkim rüzgârlar hangileridir?", d: "Batı rüzgârları", y: ["Alize rüzgârları", "Muson rüzgârları"], a: "Orta enlemlerde hava sistemleri çoğunlukla batıdan doğuya ilerler. Bunun nedeni hâkim batı rüzgârlarıdır." },
  { id: "p04-037", k: "Dünya", s: "Ekvator yakınında alizelerin buluştuğu yağışlı alçak basınç kuşağına ne ad verilir?", d: "Tropikal yakınsama kuşağı", y: ["Subtropikal yüksek basınç", "Kutup cephesi"], a: "Bu kuşakta buluşan nemli hava yükselir, bol bulut ve sağanak üretir. Mevsimlere göre kuzeye ve güneye kayar." },
  { id: "p04-038", k: "Dünya", s: "Büyük sıcak çöllerin çoğu hangi enlemler civarında yer alır?", d: "Yaklaşık 30° kuzey ve güney", y: ["Ekvator üzerinde", "Yaklaşık 60° kuzey ve güney"], a: "Bu enlemlerde yukarıdan alçalan hava ısınıp kurur. Yağış azalır ve Sahra gibi büyük çöller oluşur." },
  { id: "p04-039", k: "Dünya", s: "Hadley dolaşımında ekvatorda ısınan hava ne yapar?", d: "Yükselir", y: ["Alçalır", "Yerinde kalır"], a: "Ekvatorda ısınan hava yükselir, yukarıda kutuplara doğru ilerler ve yaklaşık 30° enlemlerinde alçalır." },
  { id: "p04-040", k: "Dünya", s: "Gündüz denizden karaya doğru esen yerel rüzgâra ne denir?", d: "Deniz meltemi", y: ["Kara meltemi", "Fön rüzgârı"], a: "Gündüz kara denizden hızlı ısınır. Karada yükselen havanın yerini denizden gelen serin hava alır." },
  { id: "p04-041", k: "Dünya", s: "Kara meltemi günün hangi saatlerinde eser?", d: "Gece", y: ["Öğle saatlerinde", "Yalnızca öğleden sonra"], a: "Gece kara denizden hızlı soğur. Bu kez hava karadan denize doğru akar." },
  { id: "p04-042", k: "Dünya", s: "Dağdan inerken ısınıp kuruyan sıcak rüzgâra ne ad verilir?", d: "Fön", y: ["Muson", "Alize"], a: "Fön rüzgârı dağ yamacından aşağı inerken sıkışır ve ısınır. Karları hızla eritebilir." },
  { id: "p04-043", k: "Dünya", s: "Mevsime göre yön değiştiren, Güney Asya'ya yazın bol yağış getiren rüzgârlar hangileridir?", d: "Muson rüzgârları", y: ["Alize rüzgârları", "Meltemler"], a: "Musonlar yazın okyanustan karaya, kışın karadan okyanusa eser. Yazın Hindistan'a yağmur getirir." },
  { id: "p04-044", k: "Dünya", s: "Yaz musonu Hindistan'a neden bol yağış getirir?", d: "Okyanustan nemli hava taşıdığı için", y: ["Çölden kuru hava taşıdığı için", "Kutup havası getirdiği için"], a: "Yazın kara ısınır ve alçak basınç oluşur. Hint Okyanusu'ndan gelen nemli hava karaya ulaşıp yağmur bırakır." },
  { id: "p04-045", k: "Dünya", s: "Jet akımları atmosferin genellikle hangi kesiminde bulunur?", d: "Troposferin üst kısmında", y: ["Yere çok yakın", "Mezosferde"], a: "Jet akımları tropopoz yakınında, yaklaşık 9-16 km yükseklikte esen dar ve çok hızlı rüzgâr kuşaklarıdır." },
  { id: "p04-046", k: "Dünya", s: "Ana jet akımları genel olarak hangi yönde akar?", d: "Batıdan doğuya", y: ["Doğudan batıya", "Kuzeyden güneye"], a: "Jet akımları dalgalı bir yol izlese de genel olarak batıdan doğuya doğru akar." },
  { id: "p04-047", k: "Dünya", s: "Kuzey yarımkürede doğuya giden uçuşlar çoğunlukla neden daha kısa sürer?", d: "Jet akımı arkadan ittiği için", y: ["Dünya'nın dönüşü uçağı taşıdığı için", "Ay'ın çekimi azaldığı için"], a: "Uçaklar batıdan doğuya akan jet akımını arkalarına alarak hızlanır ve yakıt tasarrufu yapar." },
  { id: "p04-048", k: "Dünya", s: "Rüzgârın gücünü denizde ve karada gözlenen etkilerine göre sınıflandıran ölçek hangisidir?", d: "Beaufort ölçeği", y: ["Richter ölçeği", "Mohs ölçeği"], a: "Beaufort ölçeği rüzgârı 0'dan 12'ye kadar derecelendirir. Başlangıçta denizcilerin gözlemleri için geliştirilmiştir." },
  { id: "p04-049", k: "Dünya", s: "Beaufort ölçeğinde 12 neyi ifade eder?", d: "Orkan (kasırga şiddeti)", y: ["Durgun hava", "Hafif esinti"], a: "12, ölçeğin en üst basamağıdır ve yaklaşık 118 km/sa üzerindeki rüzgârları gösterir. 0 ise tam durgunluktur." },
  { id: "p04-050", k: "Dünya", s: "Bağıl nem %100 olduğunda hava için ne söylenir?", d: "Doymuştur", y: ["Tamamen kurudur", "Kararsızdır"], a: "Bağıl nem %100 olduğunda hava o sıcaklıkta tutabileceği en fazla su buharını taşır. Fazlası yoğuşmaya başlar." },
  { id: "p04-051", k: "Dünya", s: "Hava soğurken yoğuşmanın başladığı sıcaklığa ne ad verilir?", d: "Çiy noktası", y: ["Donma noktası", "Kaynama noktası"], a: "Hava çiy noktasına kadar soğuduğunda doymuş hâle gelir ve su buharı damlacıklara dönüşmeye başlar." },
  { id: "p04-052", k: "Dünya", s: "Sıcak hava, soğuk havaya göre su buharı bakımından nasıldır?", d: "Daha fazla su buharı tutabilir", y: ["Daha az su buharı tutabilir", "Hiç su buharı tutamaz"], a: "Hava ısındıkça taşıyabileceği su buharı miktarı hızla artar. Bu yüzden sıcak bölgelerde sağanaklar çok şiddetli olabilir." },
  { id: "p04-053", k: "Dünya", s: "Serin sabahlarda otların üzerinde biriken su damlacıklarına ne denir?", d: "Çiy", y: ["Kırağı", "Dolu"], a: "Gece soğuyan yüzeylere değen havadaki su buharı yoğuşarak çiy damlacıklarını oluşturur." },
  { id: "p04-054", k: "Dünya", s: "Çiy noktası 0 °C'nin altındayken soğuk yüzeylerde oluşan buz kristallerine ne denir?", d: "Kırağı", y: ["Çiy", "Dolu"], a: "Kırağı, su buharının sıvı olmadan doğrudan buz kristali hâlinde yüzeylerde birikmesiyle oluşur." },
  { id: "p04-055", k: "Dünya", s: "Yere değecek kadar alçakta oluşan bulut tabakasına ne ad verilir?", d: "Sis", y: ["Sirrus", "Hale"], a: "Sis aslında yere yakın oluşmuş bir buluttur. Havada asılı minik su damlacıklarından oluşur." },
  { id: "p04-056", k: "Dünya", s: "Meteorolojide görüş mesafesi kaç kilometrenin altına inerse buna sis denir?", d: "1 km", y: ["10 km", "100 m"], a: "Görüş 1 km'nin altına düşerse sis, üstünde kalırsa pus ya da hafif sis olarak adlandırılır." },
  { id: "p04-057", k: "Dünya", s: "Açık ve rüzgârsız gecelerde yerin ısı kaybedip soğumasıyla oluşan sise ne denir?", d: "Radyasyon sisi", y: ["Adveksiyon sisi", "Cephe sisi"], a: "Gece yer ısısını uzaya yayar ve üstündeki havayı soğutur. Hava çiy noktasına inince sis oluşur." },
  { id: "p04-058", k: "Dünya", s: "Bulutlar nasıl oluşur?", d: "Su buharı yoğuşup damlacık ya da buz olunca", y: ["Havadaki toz yandığında", "Ozon biriktiğinde"], a: "Yükselen hava soğur, içindeki su buharı minik damlacıklara ya da buz kristallerine dönüşür." },
  { id: "p04-059", k: "Dünya", s: "Bulut damlacıklarının oluşması için havada genellikle ne bulunması gerekir?", d: "Toz ve tuz gibi minik parçacıklar", y: ["Ozon molekülleri", "Elektrik akımı"], a: "Su buharı genellikle toz, deniz tuzu ya da duman gibi minik parçacıkların üzerinde yoğuşur. Bunlara yoğuşma çekirdeği denir." },
  { id: "p04-060", k: "Dünya", s: "Yüksekte oluşan, ince tüy görünümlü buz kristali bulutlarına ne denir?", d: "Sirrus", y: ["Kümülüs", "Stratus"], a: "Sirrus bulutları çok yüksekte, buz kristallerinden oluşur ve ince tüy ya da at kuyruğu gibi görünür." },
  { id: "p04-061", k: "Dünya", s: "Gökyüzünü gri bir örtü gibi kaplayan alçak ve düz bulut hangisidir?", d: "Stratus", y: ["Sirrus", "Kümülüs"], a: "Stratus, katman anlamına gelir. Gökyüzünü düz bir tabaka gibi kaplar ve bazen çisenti bırakır." },
  { id: "p04-062", k: "Dünya", s: "Pamuk gibi kabarık, tabanı düz güzel hava bulutlarına ne ad verilir?", d: "Kümülüs", y: ["Stratus", "Sirrus"], a: "Kümülüs, yığın anlamına gelir. Güneşli günlerde yükselen sıcak hava bu kabarık bulutları oluşturur." },
  { id: "p04-063", k: "Dünya", s: "Gök gürültülü fırtınaları oluşturan dev bulut türü hangisidir?", d: "Kümülonimbüs", y: ["Altostratus", "Sirrokümülüs"], a: "Kümülonimbüs bulutları 10 km'yi aşan yüksekliklere uzanabilir. Şimşek, sağanak ve dolu bu bulutlardan gelir." },
  { id: "p04-064", k: "Dünya", s: "Bulut adlarındaki 'nimbus' sözcüğü neyi belirtir?", d: "Yağış veren", y: ["Yüksekte bulunan", "Katmanlı"], a: "Nimbus Latince yağmur bulutu anlamına gelir. Nimbostratus ve kümülonimbüs yağış veren bulutlardır." },
  { id: "p04-065", k: "Dünya", s: "Bulut adlarındaki 'alto' ön eki neyi belirtir?", d: "Orta yükseklik", y: ["Yağış", "Kabarıklık"], a: "Altostratus ve altokümülüs gibi bulutlar orta seviyede, yaklaşık 2-7 km yükseklikte oluşur." },
  { id: "p04-066", k: "Dünya", s: "Kümülonimbüs bulutunun tepesinde yayılan yassı çıkıntıya ne ad verilir?", d: "Örs", y: ["Huni", "Hale"], a: "Bulut tropopoza çarpınca daha fazla yükselemez ve yanlara yayılır. Bu yüzden tepesi demirci örsüne benzer." },
  { id: "p04-067", k: "Dünya", s: "Uluslararası bulut sınıflandırmasında kaç temel bulut cinsi vardır?", d: "10", y: ["4", "25"], a: "Dünya Meteoroloji Örgütü'nün atlası bulutları 10 temel cinse ayırır. Örneğin sirrus, kümülüs ve stratus bunlardandır." },
  { id: "p04-068", k: "Dünya", s: "Bugün kullanılan Latince bulut adlarını 19. yüzyıl başında öneren kişi kimdir?", d: "Luke Howard", y: ["Isaac Newton", "Charles Darwin"], a: "İngiliz eczacı Luke Howard 1802-1803'te bulutları kümülüs, stratus, sirrus gibi adlarla sınıflandırdı." },
  { id: "p04-069", k: "Dünya", s: "Güneş ya da Ay çevresinde görülen ışık halkası genellikle hangi bulutta oluşur?", d: "Sirrostratus", y: ["Kümülüs", "Nimbostratus"], a: "İnce sirrostratus bulutlarındaki buz kristalleri ışığı kırar ve 22 derecelik hale denen halkayı oluşturur." },
  { id: "p04-070", k: "Dünya", s: "Uzun süreli, sürekli yağış veren kalın gri bulut hangisidir?", d: "Nimbostratus", y: ["Kümülüs", "Sirrus"], a: "Nimbostratus gökyüzünü koyu gri bir örtüyle kaplar ve saatlerce süren yağmur ya da kar bırakır." },
  { id: "p04-071", k: "Dünya", s: "Uçakların arkasında bıraktığı beyaz izler çoğunlukla nasıl oluşur?", d: "Egzozdaki su buharı donunca", y: ["Yakıt dumanı biriktiğinde", "Ozon parladığında"], a: "Motor egzozundaki su buharı yüksekteki çok soğuk havada yoğuşur ve buz kristallerine dönüşür." },
  { id: "p04-072", k: "Dünya", s: "Yağmurun yere ulaşmadan havada buharlaşmasına ne denir?", d: "Virga", y: ["Sağanak", "Çisenti"], a: "Virga, bulutun altından sarkan saçak gibi görünür. Kuru havada damlalar yere varmadan buharlaşır." },
  { id: "p04-073", k: "Dünya", s: "Çok küçük damlalarla yağan hafif yağmura ne ad verilir?", d: "Çisenti", y: ["Sağanak", "Dolu"], a: "Çisentide damlalar çok küçüktür ve yavaş düşer. Genellikle alçak stratus bulutlarından gelir." },
  { id: "p04-074", k: "Dünya", s: "Dolu taneleri bulutun içinde nasıl büyür?", d: "Yukarı aşağı taşınıp buz katmanı kazanarak", y: ["Yere yakın havada donarak", "Kar taneleri eriyerek"], a: "Güçlü yukarı hava akımları buz tanelerini defalarca taşır. Her turda üzerlerine yeni buz katmanları eklenir." },
  { id: "p04-075", k: "Dünya", s: "Kar kristalleri genellikle kaç kollu ya da köşeli bir yapıya sahiptir?", d: "Altı", y: ["Dört", "Sekiz"], a: "Kar kristalleri altıgen yapıdadır. Bunun nedeni buz içindeki su moleküllerinin altıgen düzende dizilmesidir." },
  { id: "p04-076", k: "Dünya", s: "Sıvı düşüp soğuk yüzeylere değince anında donan ve yolları camla kaplar gibi buzlatan yağışa ne denir?", d: "Dondurucu yağmur", y: ["Dolu", "Çisenti"], a: "Damlalar donma noktasının altında olsa da sıvı kalabilir. Soğuk yüzeye değdikleri anda buz tabakasına dönüşür." },
  { id: "p04-077", k: "Dünya", s: "Kar ile yağmurun karışık yağmasına Türkçede ne ad verilir?", d: "Sulu sepken", y: ["Kırağı", "Tipi"], a: "Sulu sepken, kar tanelerinin düşerken kısmen eridiği ve yağmurla karışık yağdığı durumdur." },
  { id: "p04-078", k: "Dünya", s: "Kuvvetli rüzgârla birlikte yağan, görüşü ciddi biçimde azaltan kar fırtınasına ne denir?", d: "Tipi", y: ["Sulu sepken", "Kırağı"], a: "Tipide rüzgâr karı savurur. Görüş birkaç metreye kadar düşebilir ve yollar kapanabilir." },
  { id: "p04-079", k: "Dünya", s: "Nemli havanın dağ yamacına çarpıp yükselmesiyle oluşan yağışa ne ad verilir?", d: "Orografik yağış", y: ["Konvektif yağış", "Cephesel yağış"], a: "Dağa tırmanan hava soğur, yoğuşur ve yamacın rüzgâr alan tarafına bol yağış bırakır." },
  { id: "p04-080", k: "Dünya", s: "Güçlü ısınmayla yükselen havanın oluşturduğu, yaz öğleden sonraları sık görülen sağanaklara ne denir?", d: "Konvektif yağış", y: ["Orografik yağış", "Cephesel yağış"], a: "Yer ısınınca hava hızla yükselir ve kümülonimbüs bulutları oluşur. Kısa süreli, şiddetli sağanaklar görülür." },
  { id: "p04-081", k: "Dünya", s: "Dağların rüzgâr almayan, kuru kalan tarafına ne ad verilir?", d: "Yağmur gölgesi", y: ["Nem kuşağı", "Yağmur kuşağı"], a: "Hava nemini dağın öbür yamacında bırakır. İnen hava ısınıp kurur, bu yüzden arka taraf kurak kalır." },
  { id: "p04-082", k: "Dünya", s: "Sıcak ve soğuk hava kütlelerinin karşılaştığı sınıra ne denir?", d: "Cephe", y: ["Tropopoz", "İzobar"], a: "Cepheler hava değişimlerinin yaşandığı yerlerdir. Geçişleri sırasında bulutlanma ve yağış sık görülür." },
  { id: "p04-083", k: "Dünya", s: "Hava haritasında aynı basınçtaki noktaları birleştiren çizgilere ne ad verilir?", d: "İzobar", y: ["İzoterm", "Meridyen"], a: "İzobarlar basınç dağılımını gösterir. Rüzgârın yönü ve şiddeti hakkında bilgi verir." },
  { id: "p04-084", k: "Dünya", s: "Haritada aynı sıcaklıktaki noktaları birleştiren çizgiye ne denir?", d: "İzoterm", y: ["İzobar", "Paralel"], a: "İzotermler sıcaklık dağılımını gösterir. İklim haritalarında sık kullanılır." },
  { id: "p04-085", k: "Dünya", s: "Hava haritasında izobarların sık olduğu yerlerde rüzgâr nasıldır?", d: "Kuvvetlidir", y: ["Zayıftır", "Hiç esmez"], a: "İzobarlar birbirine yakınsa kısa mesafede büyük basınç farkı var demektir. Bu da güçlü rüzgâr anlamına gelir." },
  { id: "p04-086", k: "Dünya", s: "Soğuk cephe geçerken genellikle ne yaşanır?", d: "Ani sağanak ve sıcaklık düşüşü", y: ["Sıcaklıkta belirgin artış", "Günlerce süren durgun sis"], a: "Soğuk hava sıcak havanın altına girip onu hızla yukarı iter. Kısa ama sert sağanaklar ve serinleme görülür." },
  { id: "p04-087", k: "Dünya", s: "Yüksek basınç alanlarında hava genellikle nasıldır?", d: "Açık ve sakin", y: ["Yağışlı ve fırtınalı", "Sisli ve dolulu"], a: "Yüksek basınçta hava alçalır ve ısınır. Bulut oluşumu zorlaşır, gökyüzü genellikle açıktır." },
  { id: "p04-088", k: "Dünya", s: "Alçak basınç merkezinde hava hangi yönde hareket eder?", d: "Yükselir", y: ["Alçalır", "Yerinde durur"], a: "Alçak basınçta yükselen hava soğur ve yoğuşur. Bu yüzden alçak basınç bulut ve yağışla ilişkilidir." },
  { id: "p04-089", k: "Dünya", s: "Meteorolojide antisiklon neyi ifade eder?", d: "Yüksek basınç merkezini", y: ["Alçak basınç merkezini", "Tropikal fırtınayı"], a: "Antisiklonlar kuzey yarımkürede saat yönünde döner ve genellikle açık, durgun hava getirir." },
  { id: "p04-090", k: "Dünya", s: "Şimşek aslında nedir?", d: "Büyük bir elektrik boşalması", y: ["Ozonun yanması", "Bulutların çarpışması"], a: "Bulut içinde ayrışan elektrik yükleri dengelenirken dev bir kıvılcım oluşur. Buna şimşek denir." },
  { id: "p04-091", k: "Dünya", s: "Gök gürültüsüne ne yol açar?", d: "Şimşeğin havayı aniden ısıtıp genleştirmesi", y: ["Bulutların birbirine çarpması", "Dolu tanelerinin çarpışması"], a: "Şimşek kanalındaki hava bir anda çok ısınır ve patlarcasına genleşir. Bu ani genleşme gök gürültüsü olarak duyulur." },
  { id: "p04-092", k: "Dünya", s: "Şimşeği gök gürültüsünden önce görmemizin nedeni nedir?", d: "Işık sesten çok daha hızlıdır", y: ["Ses bulutlarda yansır", "Gözlerimiz kulaktan hassastır"], a: "Işık neredeyse anında gelir, ses ise saniyede yaklaşık 340 metre yol alır. Bu yüzden gürültü gecikir." },
  { id: "p04-093", k: "Dünya", s: "Şimşekten sonra gök gürültüsü 3 saniye gecikirse fırtına yaklaşık ne kadar uzaktadır?", d: "Yaklaşık 1 km", y: ["Yaklaşık 10 km", "Yaklaşık 100 m"], a: "Ses havada saniyede yaklaşık 340 m yol alır. Üç saniyelik gecikme yaklaşık bir kilometre eder." },
  { id: "p04-094", k: "Dünya", s: "Bir şimşek kanalı ne kadar sıcak olabilir?", d: "Güneş yüzeyinden birkaç kat sıcak", y: ["Kaynar su kadar", "Bir mum alevi kadar"], a: "NOAA'ya göre şimşek kanalı yaklaşık 30.000 °C'ye ulaşabilir. Bu, Güneş'in yüzeyinden birkaç kat sıcaktır." },
  { id: "p04-095", k: "Dünya", s: "Şimşeklerin çoğu nerede gerçekleşir?", d: "Bulutların içinde ya da arasında", y: ["Buluttan yere", "Yerden buluta"], a: "Şimşeklerin büyük kısmı yere hiç ulaşmaz. Bulut içinde ya da bulutlar arasında çakar." },
  { id: "p04-096", k: "Dünya", s: "Gök gürültülü fırtınada dışarıdaysanız en güvenli sığınak hangisidir?", d: "Kapalı bir bina ya da kapalı araç", y: ["Tek başına duran bir ağaç", "Açık bir tepe"], a: "Yıldırım yüksek ve yalnız noktalara düşme eğilimindedir. Kapalı binalar ve metal gövdeli araçlar koruma sağlar." },
  { id: "p04-097", k: "Dünya", s: "Paratoner (yıldırımsavar) ne işe yarar?", d: "Yıldırımı güvenle toprağa iletir", y: ["Bulutları dağıtır", "Yıldırım oluşmasını engeller"], a: "Paratoner yıldırımı yapıya zarar vermeden kablo üzerinden toprağa aktarır. Yıldırımı engellemez, yönlendirir." },
  { id: "p04-098", k: "Dünya", s: "Yıldırımsavarı icat eden kişi kimdir?", d: "Benjamin Franklin", y: ["Thomas Edison", "Nikola Tesla"], a: "Franklin 18. yüzyılda şimşeğin elektrik olduğunu gösterdi ve binaları korumak için yıldırımsavarı geliştirdi." },
  { id: "p04-099", k: "Dünya", s: "Atlantik'te ve kuzeydoğu Pasifik'te oluşan güçlü tropikal siklonlara ne ad verilir?", d: "Hurricane", y: ["Tayfun", "Tornado"], a: "Aynı tür fırtına Atlantik'te hurricane, kuzeybatı Pasifik'te tayfun, Hint Okyanusu'nda siklon diye anılır." },
  { id: "p04-100", k: "Dünya", s: "Kuzeybatı Pasifik'te oluşan güçlü tropikal siklonlara ne denir?", d: "Tayfun", y: ["Hurricane", "Tornado"], a: "Japonya, Filipinler ve Çin kıyılarını etkileyen güçlü tropikal fırtınalar tayfun olarak adlandırılır." },
  { id: "p04-101", k: "Dünya", s: "Hint Okyanusu'nda oluşan tropikal fırtınalar genellikle hangi adla anılır?", d: "Siklon", y: ["Tayfun", "Hurricane"], a: "Hint Okyanusu ve Güney Pasifik'te bu fırtınalara genellikle siklon denir." },
  { id: "p04-102", k: "Dünya", s: "Tropikal siklonlar enerjilerini esas olarak nereden alır?", d: "Sıcak okyanus suyundan", y: ["Soğuk kutup havasından", "Jet akımından"], a: "Sıcak denizden buharlaşan su yükselip yoğuşurken ısı açığa çıkar. Fırtınayı besleyen enerji budur." },
  { id: "p04-103", k: "Dünya", s: "Tropikal siklon oluşumu için deniz yüzeyi sıcaklığı genellikle en az kaç derece olmalıdır?", d: "Yaklaşık 26 °C", y: ["Yaklaşık 10 °C", "Yaklaşık 40 °C"], a: "NOAA'ya göre kasırgaların gelişmesi için deniz yüzeyinin genellikle yaklaşık 26 °C ya da daha sıcak olması gerekir." },
  { id: "p04-104", k: "Dünya", s: "Bir kasırganın merkezindeki sakin ve çoğu zaman açık bölgeye ne denir?", d: "Göz", y: ["Duvar", "Kuyruk"], a: "Kasırganın gözünde rüzgâr zayıftır ve gökyüzü açık olabilir. Göz geçtikten sonra fırtına ters yönden yeniden başlar." },
  { id: "p04-105", k: "Dünya", s: "Bir kasırgada en şiddetli rüzgârlar nerede eser?", d: "Göz duvarında", y: ["Gözün tam ortasında", "Fırtınanın dış kenarlarında"], a: "Gözü çevreleyen bulut halkası olan göz duvarında en güçlü rüzgârlar ve en yoğun yağış görülür." },
  { id: "p04-106", k: "Dünya", s: "Kasırgalar karaya çıktıktan sonra neden zayıflar?", d: "Sıcak su kaynağından koptukları için", y: ["Kara havası daha nemli olduğu için", "Ay'ın çekimi değiştiği için"], a: "Karada fırtınayı besleyen sıcak deniz suyu yoktur. Ayrıca sürtünme rüzgârları yavaşlatır." },
  { id: "p04-107", k: "Dünya", s: "Fırtına rüzgârlarının deniz suyunu kıyıya yığarak su seviyesini yükseltmesine ne denir?", d: "Fırtına kabarması", y: ["Tsunami", "Gelgit"], a: "Fırtına kabarması kıyı bölgelerinde ciddi taşkınlara yol açar. Kasırgaların en tehlikeli yönlerinden biridir." },
  { id: "p04-108", k: "Dünya", s: "Saffir-Simpson ölçeği neyi sınıflandırır?", d: "Kasırgaları", y: ["Hortumları", "Kar fırtınalarını"], a: "Saffir-Simpson ölçeği kasırgaları sürekli rüzgâr hızına göre 1'den 5'e kadar derecelendirir." },
  { id: "p04-109", k: "Dünya", s: "Saffir-Simpson ölçeğinde en yüksek kasırga kategorisi kaçtır?", d: "5", y: ["3", "10"], a: "Kategori 5, sürekli rüzgârın yaklaşık 252 km/sa'i aştığı en yıkıcı kasırgaları gösterir." },
  { id: "p04-110", k: "Dünya", s: "Tropikal siklonlar ekvatorun hemen çevresinde neden çok nadir oluşur?", d: "Coriolis etkisi orada çok zayıftır", y: ["Deniz suyu orada çok soğuktur", "Orada hiç rüzgâr esmez"], a: "Fırtınanın dönmeye başlaması için Coriolis etkisi gerekir. Bu etki ekvatorda neredeyse sıfırdır." },
  { id: "p04-111", k: "Dünya", s: "Güney yarımkürede tropikal siklonlar hangi yönde döner?", d: "Saat yönünde", y: ["Saat yönünün tersine", "Hiç dönmez"], a: "Coriolis etkisinin yönü güney yarımkürede terstir. Bu yüzden siklonlar orada saat yönünde döner." },
  { id: "p04-112", k: "Dünya", s: "Tropikal fırtınalara verilecek isim listelerini hangi kuruluş belirler?", d: "Dünya Meteoroloji Örgütü", y: ["NASA", "UNESCO"], a: "İsim listeleri Dünya Meteoroloji Örgütü'nün bölgesel komitelerince hazırlanır. Çok yıkıcı fırtınaların adları listeden çıkarılır." },
  { id: "p04-113", k: "Dünya", s: "Hortum (tornado) nedir?", d: "Buluttan yere uzanan dönen hava sütunu", y: ["Okyanusta oluşan dev dalga", "Çölde esen sabit rüzgâr"], a: "Hortum, fırtına bulutundan yere kadar uzanan, çok hızlı dönen dar bir hava sütunudur." },
  { id: "p04-114", k: "Dünya", s: "Hortumların en sık görüldüğü ülke hangisidir?", d: "ABD", y: ["Hindistan", "Brezilya"], a: "ABD'de her yıl ortalama bin kadar hortum kaydedilir. Bu sayı dünyadaki diğer ülkelerin çok üzerindedir." },
  { id: "p04-115", k: "Dünya", s: "ABD'nin orta kesiminde hortumların sık görüldüğü bölgeye ne ad verilir?", d: "Tornado Koridoru", y: ["Kasırga Kuşağı", "Güneş Kuşağı"], a: "Tornado Koridoru'nda güneyden gelen sıcak ve nemli hava ile kuzeyden gelen kuru ve soğuk hava sık sık karşılaşır." },
  { id: "p04-116", k: "Dünya", s: "Hortumları yol açtıkları hasara göre derecelendiren ölçek hangisidir?", d: "Geliştirilmiş Fujita ölçeği", y: ["Saffir-Simpson ölçeği", "Beaufort ölçeği"], a: "EF ölçeği hortumları EF0'dan EF5'e kadar sınıflandırır. Rüzgâr hızı hasara bakılarak tahmin edilir." },
  { id: "p04-117", k: "Dünya", s: "Güçlü hortumların çoğunu hangi tür fırtına üretir?", d: "Süper hücre fırtınası", y: ["Kar fırtınası", "Kum fırtınası"], a: "Süper hücreler, içinde dönen güçlü bir yukarı akım bulunan uzun ömürlü gök gürültülü fırtınalardır." },
  { id: "p04-118", k: "Dünya", s: "Su yüzeyi üzerinde oluşan hortuma ne denir?", d: "Deniz hortumu", y: ["Girdap", "Tsunami"], a: "Deniz hortumları göl ve deniz üzerinde görülür. Genellikle karadaki hortumlardan daha zayıftır." },
  { id: "p04-119", k: "Dünya", s: "Hangisi genellikle çok daha geniş bir alanı kaplar?", d: "Tropikal kasırga", y: ["Hortum", "Toz şeytanı"], a: "Kasırgalar yüzlerce kilometre genişliğe ulaşabilir. Hortumların genişliği ise çoğunlukla birkaç yüz metreyi geçmez." },
  { id: "p04-120", k: "Dünya", s: "Bir hortum genellikle ne kadar sürer?", d: "Çoğunlukla birkaç dakika", y: ["Birkaç hafta", "Birkaç ay"], a: "Hortumların çoğu 10 dakikadan kısa sürer. Kasırgalar ise günlerce yaşayabilir." },
  { id: "p04-121", k: "Dünya", s: "Sıcak ve güneşli günlerde çölde oluşan küçük dönen toz sütununa ne denir?", d: "Toz şeytanı", y: ["Süper hücre", "Deniz hortumu"], a: "Toz şeytanı, ısınan yerden yükselen havanın dönmesiyle oluşur. Bulutla bağlantısı yoktur ve genellikle zararsızdır." },
  { id: "p04-122", k: "Dünya", s: "Fırtına bulutundan inen hava akımının kaldırdığı dev toz duvarına ne ad verilir?", d: "Habub", y: ["Sirokko", "Muson"], a: "Habub, Sudan ve Arabistan gibi kurak bölgelerde görülür. Kilometrelerce genişlikte bir toz duvarı ilerler." },
  { id: "p04-123", k: "Dünya", s: "Sahra'dan Akdeniz'e doğru esen sıcak ve tozlu rüzgâra ne ad verilir?", d: "Sirokko", y: ["Mistral", "Bora"], a: "Sirokko Kuzey Afrika'dan gelir. Güney Avrupa'ya sıcak hava ve Sahra tozu taşır." },
  { id: "p04-124", k: "Dünya", s: "Fransa'da Rhône vadisinden Akdeniz'e doğru esen soğuk ve kuvvetli rüzgâr hangisidir?", d: "Mistral", y: ["Sirokko", "Fön"], a: "Mistral kuzeyden gelen soğuk havayı vadi boyunca hızlandırır. Güney Fransa'da açık ve serin hava getirir." },
  { id: "p04-125", k: "Dünya", s: "Türkiye'de kuzeydoğudan esen soğuk rüzgâra ne ad verilir?", d: "Poyraz", y: ["Lodos", "Kıble"], a: "Poyraz kuzeydoğudan eser ve özellikle kışın serin, kuru hava getirir." },
  { id: "p04-126", k: "Dünya", s: "Güneybatıdan esen, İstanbul'da sık fırtınalara yol açan ılık rüzgâr hangisidir?", d: "Lodos", y: ["Poyraz", "Karayel"], a: "Lodos ılık ve nemli bir rüzgârdır. Marmara'da denizi kabartır, vapur seferlerini aksatabilir." },
  { id: "p04-127", k: "Dünya", s: "Türkiye'de kuzeybatıdan esen rüzgâra ne denir?", d: "Karayel", y: ["Keşişleme", "Lodos"], a: "Karayel kuzeybatıdan eser. Keşişleme güneydoğudan, lodos güneybatıdan esen rüzgârdır." },
  { id: "p04-128", k: "Dünya", s: "Büyük kentlerin çevresindeki kırsal alanlardan daha sıcak olmasına ne ad verilir?", d: "Kentsel ısı adası", y: ["Sera etkisi", "Albedo etkisi"], a: "Beton ve asfalt gün boyu ısıyı emer, gece yavaş bırakır. Bu yüzden kentler özellikle geceleri daha sıcak kalır." },
  { id: "p04-129", k: "Dünya", s: "Bir yüzeyin üzerine düşen güneş ışığını yansıtma oranına ne denir?", d: "Albedo", y: ["Nem", "Basınç"], a: "Albedo 0 ile 1 arasında ifade edilir. Açık renkli yüzeyler çok, koyu renkli yüzeyler az ışık yansıtır." },
  { id: "p04-130", k: "Dünya", s: "Aşağıdaki yüzeylerden hangisinin albedosu en yüksektir?", d: "Taze kar", y: ["Açık okyanus", "Asfalt"], a: "Taze kar güneş ışığının büyük kısmını yansıtır. Okyanus ve asfalt ise ışığın çoğunu emer." },
  { id: "p04-131", k: "Dünya", s: "Sera etkisi nedir?", d: "Bazı gazların yerden yayılan ısıyı tutması", y: ["Ozonun güneş ışığını engellemesi", "Güneş'in daha çok ışık vermesi"], a: "Karbondioksit ve su buharı gibi gazlar yerden yayılan ısının bir kısmını tutar. Bu doğal etki yaşamı mümkün kılar." },
  { id: "p04-132", k: "Dünya", s: "Doğal sera etkisi olmasaydı Dünya'nın ortalama yüzey sıcaklığı yaklaşık kaç derece olurdu?", d: "Yaklaşık -18 °C", y: ["Yaklaşık 15 °C", "Yaklaşık 40 °C"], a: "Sera gazları sayesinde ortalama sıcaklık yaklaşık 15 °C'dir. Bu gazlar olmasaydı gezegen donmuş olurdu." },
  { id: "p04-133", k: "Dünya", s: "Doğal sera etkisine en büyük katkıyı yapan gaz hangisidir?", d: "Su buharı", y: ["Azot", "Oksijen"], a: "Su buharı en etkili doğal sera gazıdır. Ancak miktarı sıcaklığa bağlıdır ve ısınmayı büyütücü bir rol oynar." },
  { id: "p04-134", k: "Dünya", s: "İnsan kaynaklı küresel ısınmaya en büyük katkıyı yapan gaz hangisidir?", d: "Karbondioksit", y: ["Argon", "Azot"], a: "Fosil yakıtların yakılmasıyla salınan karbondioksit, insan kaynaklı ısınmanın en büyük payına sahiptir." },
  { id: "p04-135", k: "Dünya", s: "Metan, karbondioksitle karşılaştırıldığında molekül başına ısıyı nasıl tutar?", d: "Çok daha güçlü tutar", y: ["Hiç tutmaz", "Daha zayıf tutar"], a: "Metan atmosferde daha kısa kalır ama kısa vadede ısıyı karbondioksitten onlarca kat güçlü tutar." },
  { id: "p04-136", k: "Dünya", s: "Sığır gibi geviş getiren hayvanların sindirimiyle havaya karışan sera gazı hangisidir?", d: "Metan", y: ["Ozon", "Argon"], a: "Geviş getiren hayvanların midesindeki mikroplar metan üretir. Hayvancılık önemli bir metan kaynağıdır." },
  { id: "p04-137", k: "Dünya", s: "Tarımda azotlu gübre kullanımıyla artan güçlü sera gazı hangisidir?", d: "Diazot monoksit (N₂O)", y: ["Argon", "Neon"], a: "Diazot monoksit güçlü bir sera gazıdır. Atmosferdeki artışının büyük kısmı tarımsal gübrelerden kaynaklanır." },
  { id: "p04-138", k: "Dünya", s: "Hawaii'deki Mauna Loa'da 1958'de düzenli karbondioksit ölçümlerini başlatan bilim insanı kimdir?", d: "Charles David Keeling", y: ["Svante Arrhenius", "Edwin Hubble"], a: "Keeling'in başlattığı ölçümler bugün de sürüyor. Karbondioksitteki artışı gösteren grafiğe Keeling eğrisi denir." },
  { id: "p04-139", k: "Dünya", s: "Karbondioksit artışının Dünya'yı ısıtacağını 1896'da hesaplayan İsveçli bilim insanı kimdir?", d: "Svante Arrhenius", y: ["Anders Celsius", "Alfred Nobel"], a: "Arrhenius, havadaki karbondioksit miktarının değişmesinin yüzey sıcaklığını nasıl etkileyeceğini ilk hesaplayanlardandır." },
  { id: "p04-140", k: "Dünya", s: "Sanayi Devrimi öncesinde atmosferdeki karbondioksit yaklaşık kaç ppm idi?", d: "Yaklaşık 280 ppm", y: ["Yaklaşık 28 ppm", "Yaklaşık 2800 ppm"], a: "Buz çekirdekleri sanayi öncesi düzeyin yaklaşık 280 ppm olduğunu gösterir. ppm, milyonda bir parça demektir." },
  { id: "p04-141", k: "Dünya", s: "Bugün atmosferdeki karbondioksit sanayi öncesi düzeye göre nasıldır?", d: "Yaklaşık %50 daha fazla", y: ["Yaklaşık aynı", "Yaklaşık on kat fazla"], a: "Karbondioksit 280 ppm civarından 420 ppm'in üzerine çıktı. Bu yaklaşık yüzde elli artış demektir." },
  { id: "p04-142", k: "Dünya", s: "Mauna Loa karbondioksit eğrisindeki yıllık iniş çıkışın nedeni nedir?", d: "Kuzey yarımkürede bitkilerin mevsimsel büyümesi", y: ["Volkan patlamaları", "Ay'ın evreleri"], a: "Kuzey yarımkürede bitkiler yazın karbondioksit emer, kışın çürüyen bitkiler geri salar. Eğri bu yüzden her yıl dalgalanır." },
  { id: "p04-143", k: "Dünya", s: "IPCC'ye göre 20. yüzyıl ortasından beri gözlenen ısınmanın başlıca nedeni nedir?", d: "İnsan etkinlikleri", y: ["Güneş'in parlaklaşması", "Volkanlar"], a: "IPCC, insan etkinliklerinin atmosferi, okyanusları ve karaları ısıttığının açık olduğunu belirtir. Başlıca etken fosil yakıtlardır." },
  { id: "p04-144", k: "Dünya", s: "Küresel ortalama yüzey sıcaklığı sanayi öncesine göre yaklaşık ne kadar arttı?", d: "1 °C'den biraz fazla", y: ["Yaklaşık 5 °C", "Yaklaşık 0,1 °C"], a: "Ölçümler küresel ortalama sıcaklığın 19. yüzyıl sonuna göre 1 °C'den biraz fazla arttığını gösterir." },
  { id: "p04-145", k: "Dünya", s: "IPCC'yi (Hükümetlerarası İklim Değişikliği Paneli) 1988'de hangi iki kuruluş kurdu?", d: "WMO ve UNEP", y: ["UNESCO ve WHO", "FAO ve UNICEF"], a: "IPCC, Dünya Meteoroloji Örgütü ve BM Çevre Programı tarafından iklim bilimini değerlendirmek için kuruldu." },
  { id: "p04-146", k: "Dünya", s: "Paris İklim Anlaşması küresel ısınmayı hangi sınırın 'epey altında' tutmayı hedefler?", d: "2 °C", y: ["4 °C", "0,5 °C"], a: "Anlaşma ısınmayı sanayi öncesine göre 2 °C'nin epey altında tutmayı, mümkünse 1,5 °C ile sınırlamayı amaçlar." },
  { id: "p04-147", k: "Dünya", s: "Paris İklim Anlaşması hangi yıl kabul edildi?", d: "2015", y: ["1997", "2009"], a: "Anlaşma Aralık 2015'te Paris'teki iklim zirvesinde kabul edildi. Kyoto Protokolü ise 1997 tarihlidir." },
  { id: "p04-148", k: "Dünya", s: "Küresel deniz seviyesinin yükselmesinin iki ana nedeni nedir?", d: "Kara buzlarının erimesi ve suyun genleşmesi", y: ["Yağmurun ve nehirlerin artması", "Deniz buzunun erimesi ve dalgalar"], a: "Buzullardan denize su eklenir, ısınan deniz suyu da genleşir. İkisi birlikte deniz seviyesini yükseltir." },
  { id: "p04-149", k: "Dünya", s: "Kuzey Kutbu'ndaki yüzen deniz buzu tamamen erise deniz seviyesi nasıl değişirdi?", d: "Neredeyse hiç değişmezdi", y: ["Onlarca metre yükselirdi", "Belirgin biçimde düşerdi"], a: "Yüzen buz zaten kendi ağırlığı kadar su taşırır. Eridiğinde deniz seviyesini neredeyse değiştirmez. Asıl etkiyi kara buzları yapar." },
  { id: "p04-150", k: "Dünya", s: "Küresel ortalama deniz seviyesi 1880'den bu yana yaklaşık ne kadar yükseldi?", d: "Yaklaşık 20 cm", y: ["Yaklaşık 2 m", "Yaklaşık 2 mm"], a: "NASA ve NOAA verilerine göre deniz seviyesi 1880'den beri yaklaşık 20-23 cm yükseldi ve yükseliş hızlanıyor." },
  { id: "p04-151", k: "Dünya", s: "Okyanus asitlenmesinin temel nedeni nedir?", d: "Okyanusun karbondioksit emmesi", y: ["Tuzluluğun artması", "Petrol sızıntıları"], a: "Okyanusa geçen karbondioksit suyla tepkimeye girip karbonik asit oluşturur. Bu da suyun pH değerini düşürür." },
  { id: "p04-152", k: "Dünya", s: "Sera gazlarının tuttuğu fazla ısının yaklaşık ne kadarını okyanuslar emmiştir?", d: "Yaklaşık %90", y: ["Yaklaşık %10", "Yaklaşık %50"], a: "NASA ve NOAA'ya göre fazla ısının yaklaşık %90'ı okyanuslara geçti. Bu, deniz suyunun ısınmasına yol açıyor." },
  { id: "p04-153", k: "Dünya", s: "Mercan ağarmasını en çok ne tetikler?", d: "Deniz suyunun aşırı ısınması", y: ["Suyun soğuması", "Tuzun azalması"], a: "Su fazla ısınınca mercanlar içlerindeki renkli algleri dışarı atar ve beyazlar. Bu durum uzun sürerse mercanlar ölebilir." },
  { id: "p04-154", k: "Dünya", s: "Permafrost nedir?", d: "En az iki yıl üst üste donmuş kalan zemin", y: ["Her yaz eriyen buzul", "Kutup denizlerindeki buz"], a: "Permafrost Sibirya, Kanada ve Alaska'da geniş alanlar kaplar. İçinde binlerce yıllık bitki kalıntısı saklıdır." },
  { id: "p04-155", k: "Dünya", s: "Permafrost eridikçe atmosfere hangi sera gazları salınabilir?", d: "Karbondioksit ve metan", y: ["Ozon ve argon", "Helyum ve neon"], a: "Çözülen topraktaki eski bitki kalıntılarını mikroplar parçalar. Bu süreçte karbondioksit ve metan açığa çıkar." },
  { id: "p04-156", k: "Dünya", s: "Isınan havanın daha çok su buharı tutması ve bunun ısınmayı artırması neye örnektir?", d: "Pozitif geri besleme", y: ["Negatif geri besleme", "Termohalin dolaşım"], a: "Bir değişimin kendini büyütmesine pozitif geri besleme denir. Su buharı iklimdeki en güçlü geri beslemelerden biridir." },
  { id: "p04-157", k: "Dünya", s: "İklim ile hava durumu arasındaki temel fark nedir?", d: "İklim uzun yılların ortalamasıdır", y: ["İklim günlük değişimdir", "İkisi tamamen aynıdır"], a: "Hava durumu bugün ve yarın ne olacağını anlatır. İklim ise bir bölgede uzun yıllar boyunca beklenen ortalama koşullardır." },
  { id: "p04-158", k: "Dünya", s: "İklim ortalamaları genellikle kaç yıllık veriyle hesaplanır?", d: "30 yıl", y: ["5 yıl", "100 yıl"], a: "Dünya Meteoroloji Örgütü iklim normalleri için 30 yıllık dönemleri temel alır." },
  { id: "p04-159", k: "Dünya", s: "Köppen iklim sınıflandırmasında 'A' grubu hangi iklimleri kapsar?", d: "Tropikal iklimler", y: ["Kurak iklimler", "Kutup iklimleri"], a: "Köppen sisteminde A tropikal, B kurak, C ılıman, D karasal (soğuk), E ise kutup iklimlerini gösterir." },
  { id: "p04-160", k: "Dünya", s: "Köppen iklim sınıflandırmasında 'B' grubu neyi ifade eder?", d: "Kurak iklimler", y: ["Tropikal iklimler", "Ilıman iklimler"], a: "B grubu buharlaşmanın yağıştan fazla olduğu çöl ve yarı kurak bozkır iklimlerini içerir." },
  { id: "p04-161", k: "Dünya", s: "Yazları sıcak ve kurak, kışları ılık ve yağışlı geçen iklim hangisidir?", d: "Akdeniz iklimi", y: ["Karasal iklim", "Muson iklimi"], a: "Akdeniz iklimi yalnızca Akdeniz çevresinde değil, Kaliforniya ve Şili'nin bazı kıyılarında da görülür." },
  { id: "p04-162", k: "Dünya", s: "Akdeniz ikliminin tipik bitki örtüsü hangisidir?", d: "Maki", y: ["Tayga", "Tundra"], a: "Maki, kurak yazlara dayanıklı, sık ve sert yapraklı çalılardan oluşur. Defne ve kocayemiş bunlara örnektir." },
  { id: "p04-163", k: "Dünya", s: "Yaz ile kış arasındaki sıcaklık farkının büyük, kışların sert geçtiği iklim hangisidir?", d: "Karasal iklim", y: ["Okyanusal iklim", "Akdeniz iklimi"], a: "Denizden uzak iç kesimlerde yazlar sıcak, kışlar çok soğuk geçer. Doğu Anadolu buna örnektir." },
  { id: "p04-164", k: "Dünya", s: "Kıyılardan iç kesimlere gidildikçe yıllık sıcaklık farkı genellikle nasıl değişir?", d: "Artar", y: ["Azalır", "Değişmez"], a: "Deniz ısıyı yavaş alıp yavaş verdiği için kıyılarda sıcaklıklar daha dengelidir. İç kesimlerde fark büyür." },
  { id: "p04-165", k: "Dünya", s: "Denizlerin kıyı iklimini yumuşatmasının temel nedeni nedir?", d: "Suyun ısı sığasının yüksek olması", y: ["Suyun tuzlu olması", "Dalgaların rüzgâr üretmesi"], a: "Su, karaya göre çok daha fazla ısı depolar ve sıcaklığını yavaş değiştirir. Bu yüzden kıyılar yazın serin, kışın ılık olur." },
  { id: "p04-166", k: "Dünya", s: "Türkiye'de her mevsim yağışlı bir iklimin görüldüğü kıyı bölgesi hangisidir?", d: "Karadeniz kıyıları", y: ["Ege kıyıları", "Akdeniz kıyıları"], a: "Karadeniz kıyılarında nemli hava dağlara çarpıp yükselir. Bu yüzden yılın her mevsiminde yağış görülür." },
  { id: "p04-167", k: "Dünya", s: "Yıl boyu sıcak ve hemen her gün yağışlı olan, ekvator çevresindeki iklim hangisidir?", d: "Ekvatoral iklim", y: ["Savan iklimi", "Tundra iklimi"], a: "Ekvatoral iklimde mevsimler belirgin değildir. Sıcak ve nemli hava tropikal yağmur ormanlarını besler." },
  { id: "p04-168", k: "Dünya", s: "Yağışlı ve kurak mevsimleri olan, uzun otlar ve seyrek ağaçlarla kaplı tropikal bölgelere ne denir?", d: "Savan", y: ["Tundra", "Tayga"], a: "Savanlar özellikle Afrika'da yaygındır. Zebra, zürafa ve fil gibi hayvanların yaşadığı geniş otlaklardır." },
  { id: "p04-169", k: "Dünya", s: "Kuzey yarımkürenin yüksek enlemlerinde uzanan iğne yapraklı orman kuşağına ne ad verilir?", d: "Tayga", y: ["Savan", "Maki"], a: "Tayga Kanada, İskandinavya ve Sibirya boyunca uzanır. Çam, ladin ve köknar gibi ağaçlardan oluşur." },
  { id: "p04-170", k: "Dünya", s: "Kutuplara yakın, ağaçsız, yosun ve likenlerle kaplı bölgelere ne denir?", d: "Tundra", y: ["Tayga", "Bozkır"], a: "Tundrada yazlar kısa ve serindir. Toprağın altı çoğunlukla donmuştur, bu yüzden ağaçlar yetişemez." },
  { id: "p04-171", k: "Dünya", s: "Orta enlemlerde, yağışın ağaçlara yetmediği geniş çayır alanlarına Türkçede ne ad verilir?", d: "Bozkır", y: ["Maki", "Tundra"], a: "Bozkırlar (stepler) İç Anadolu ve Orta Asya'da yaygındır. İlkbaharda yeşeren otlar yazın kurur." },
  { id: "p04-172", k: "Dünya", s: "Dünya'da mevsimlerin oluşmasının asıl nedeni nedir?", d: "Dünya ekseninin eğik olması", y: ["Güneş'e uzaklığın değişmesi", "Ay'ın çekimi"], a: "Eğik eksen yüzünden yarımküreler yıl boyunca sırayla daha dik ışık alır. Güneş'e uzaklıktaki değişim mevsimlere yol açmaz." },
  { id: "p04-173", k: "Dünya", s: "Dünya'nın dönme ekseni yörünge düzlemine göre yaklaşık kaç derece eğiktir?", d: "23,5°", y: ["45°", "5°"], a: "Eksen eğikliği yaklaşık 23,5 derecedir. Dönencelerin ve kutup dairelerinin yerini bu açı belirler." },
  { id: "p04-174", k: "Dünya", s: "Dünya Güneş'e en yakın konumdayken (Ocak başı) kuzey yarımkürede hangi mevsim yaşanır?", d: "Kış", y: ["Yaz", "İlkbahar"], a: "Dünya Ocak başında Güneş'e en yakındır, ama kuzey yarımküre o sırada kıştadır. Bu, mevsimleri uzaklığın belirlemediğini gösterir." },
  { id: "p04-175", k: "Dünya", s: "Yengeç Dönencesi yaklaşık hangi enlemdedir?", d: "23,5° kuzey", y: ["0°", "66,5° kuzey"], a: "Yengeç Dönencesi, Güneş ışınlarının yaz gündönümünde öğle vakti dik geldiği en kuzeydeki enlemdir." },
  { id: "p04-176", k: "Dünya", s: "Güneş ışınlarının yılda en az bir kez öğle vakti dik geldiği bölge hangisidir?", d: "İki dönence arası", y: ["Kutup daireleri ile kutuplar arası", "Kutup daireleri arasındaki her yer"], a: "Güneş öğle vakti yalnızca Yengeç ve Oğlak dönenceleri arasındaki bölgede tam tepeye gelebilir." },
  { id: "p04-177", k: "Dünya", s: "Kutup daireleri yaklaşık hangi enlemlerdedir?", d: "66,5°", y: ["23,5°", "45°"], a: "Kutup dairelerinin ötesinde yılın en az bir gününde Güneş hiç batmaz, en az bir gününde de hiç doğmaz." },
  { id: "p04-178", k: "Dünya", s: "Kutup dairelerinin ötesinde yazın Güneş'in gece de batmamasına ne denir?", d: "Gece yarısı güneşi", y: ["Kutup ışığı", "Güneş tutulması"], a: "Norveç'in kuzeyi ve Alaska gibi yerlerde yaz ortasında Güneş gece yarısı bile ufkun üstünde kalır." },
  { id: "p04-179", k: "Dünya", s: "Kuzey Kutbu noktasında yıl boyunca gündüz ve gece nasıl dağılır?", d: "Yaklaşık 6 ay gündüz, 6 ay gece", y: ["Her gün 12 saat gündüz", "Her ay bir hafta gece"], a: "Kutup noktasında Güneş ilkbahar ekinoksunda doğar ve yaklaşık altı ay sonra, sonbahar ekinoksunda batar." },
  { id: "p04-180", k: "Dünya", s: "Dönenceler ile kutup daireleri arasında kalan matematik iklim kuşağına ne denir?", d: "Ilıman kuşak", y: ["Sıcak kuşak", "Soğuk kuşak"], a: "Ilıman kuşakta dört mevsim belirgindir. Türkiye de kuzey yarımkürenin ılıman kuşağında yer alır." },
  { id: "p04-181", k: "Dünya", s: "Ekinoks günlerinde öğle vakti Güneş ışınları hangi enleme dik gelir?", d: "Ekvator", y: ["Yengeç Dönencesi", "Kutup dairesi"], a: "Mart ve Eylül ekinokslarında Güneş ekvatorun tam tepesindedir. O günlerde gece ve gündüz hemen her yerde yaklaşık eşittir." },
  { id: "p04-182", k: "Dünya", s: "Kuzey yarımkürede en uzun gündüz yılın hangi tarihinde yaşanır?", d: "21 Haziran civarı", y: ["21 Mart civarı", "21 Aralık civarı"], a: "Yaz gündönümünde Güneş Yengeç Dönencesi'ne dik gelir. Kuzey yarımkürede en uzun gündüz bu tarihtedir." },
  { id: "p04-183", k: "Dünya", s: "Aralık ayında güney yarımkürede hangi mevsim yaşanır?", d: "Yaz", y: ["Kış", "Sonbahar"], a: "Mevsimler iki yarımkürede terstir. Avustralya ve Arjantin'de Noel yaz ortasına denk gelir." },
  { id: "p04-184", k: "Dünya", s: "Ekvator üzerinde gündüz süresi yıl boyunca nasıldır?", d: "Hep yaklaşık 12 saat", y: ["Yazın 20 saat", "Kışın 4 saat"], a: "Ekvatorda gündüz ile gece yıl boyunca neredeyse eşittir. Gün uzunluğu kutuplara gidildikçe mevsime göre daha çok değişir." },
  { id: "p04-185", k: "Dünya", s: "Enlem arttıkça yani kutuplara yaklaştıkça ortalama sıcaklık genel olarak nasıl değişir?", d: "Azalır", y: ["Artar", "Değişmez"], a: "Yüksek enlemlere güneş ışınları daha eğik gelir. Aynı enerji daha geniş alana yayıldığı için sıcaklık düşer." },
  { id: "p04-186", k: "Dünya", s: "Yüksek enlemlerin daha soğuk olmasının temel nedeni nedir?", d: "Güneş ışınlarının eğik gelmesi", y: ["Güneş'e daha uzak olmaları", "Okyanuslardan uzak olmaları"], a: "Eğik gelen ışınlar daha geniş alana yayılır ve atmosferde daha uzun yol alır. Birim alana düşen enerji azalır." },
  { id: "p04-187", k: "Dünya", s: "Aynı enlemdeki yüksek dağ zirveleri neden ovalardan soğuktur?", d: "Yükselen hava genleşip soğuduğu için", y: ["Güneş'ten daha uzak oldukları için", "Rüzgâr hep kuzeyden estiği için"], a: "Yükseklerde hava basıncı düşüktür. Hava genleşerek soğur ve seyrek hava ısıyı daha az tutar." },
  { id: "p04-188", k: "Dünya", s: "Ekvator ile kutuplar arasındaki ısı farkını dengeleyen iki büyük sistem hangileridir?", d: "Atmosfer ve okyanus dolaşımı", y: ["Volkanlar ve depremler", "Ay ve gelgitler"], a: "Rüzgârlar ve okyanus akıntıları ekvatordaki fazla ısıyı kutuplara doğru taşır." },
  { id: "p04-189", k: "Dünya", s: "Kutupların üzerinde dönen geniş ve soğuk alçak basınç alanına ne ad verilir?", d: "Kutup girdabı", y: ["Hadley hücresi", "Tropikal siklon"], a: "Kutup girdabı zayıflayıp dalgalandığında soğuk kutup havası orta enlemlere kadar inebilir." },
  { id: "p04-190", k: "Dünya", s: "Su buharı yoğuşarak sıvıya dönüşürken ne olur?", d: "Isı açığa çıkar", y: ["Isı emilir", "Hiçbir enerji değişimi olmaz"], a: "Buharlaşma sırasında emilen gizli ısı, yoğuşma sırasında geri verilir. Fırtınaları besleyen enerjinin önemli kaynağı budur." },
  { id: "p04-191", k: "Dünya", s: "Su döngüsünü harekete geçiren temel enerji kaynağı nedir?", d: "Güneş", y: ["Ay", "Dünya'nın çekirdeği"], a: "Güneş enerjisi suyu buharlaştırır ve havayı hareket ettirir. Yerçekimi de yağışın düşmesini ve suyun akmasını sağlar." },
  { id: "p04-192", k: "Dünya", s: "Suyun sıvı hâlden gaz hâline geçmesine ne denir?", d: "Buharlaşma", y: ["Yoğuşma", "Süblimleşme"], a: "Buharlaşma özellikle okyanus yüzeyinde gerçekleşir. Atmosfere geçen su buharının büyük kısmı okyanuslardan gelir." },
  { id: "p04-193", k: "Dünya", s: "Bitkilerin yapraklarından havaya su buharı salmasına ne ad verilir?", d: "Terleme", y: ["Yoğuşma", "Sızma"], a: "Bitkiler köklerinden aldıkları suyun büyük kısmını yapraklarındaki gözeneklerden buhar olarak havaya verir." },
  { id: "p04-194", k: "Dünya", s: "Buzun sıvıya dönüşmeden doğrudan su buharına geçmesine ne denir?", d: "Süblimleşme", y: ["Erime", "Yoğuşma"], a: "Kuru ve rüzgârlı havada kar ve buz erimeden buharlaşabilir. Yüksek dağlarda kar örtüsü bu yolla da azalır." },
  { id: "p04-195", k: "Dünya", s: "Yağmur suyunun toprağa işlemesine ne ad verilir?", d: "Sızma", y: ["Akış", "Terleme"], a: "Sızan su toprağı nemlendirir ve bir kısmı derinlere inerek yeraltı suyunu besler." },
  { id: "p04-196", k: "Dünya", s: "Yeraltı suyunu depolayan ve ileten geçirgen kayaç katmanına ne denir?", d: "Akifer", y: ["Delta", "Moren"], a: "Akiferler kum, çakıl ya da çatlaklı kayaçlardan oluşur. Kuyular bu katmanlardan su çeker." },
  { id: "p04-197", k: "Dünya", s: "Dünya'daki suyun yaklaşık ne kadarı okyanuslarda bulunur?", d: "Yaklaşık %97", y: ["Yaklaşık %70", "Yaklaşık %50"], a: "Suyun yaklaşık %97'si tuzludur ve okyanuslardadır. Tatlı su toplam suyun yalnızca yaklaşık %3'üdür." },
  { id: "p04-198", k: "Dünya", s: "Dünya yüzeyinin yaklaşık ne kadarı okyanuslarla kaplıdır?", d: "Yaklaşık %71", y: ["Yaklaşık %50", "Yaklaşık %90"], a: "Yeryüzünün yaklaşık %71'i okyanus ve denizlerle kaplıdır. Uzaydan Dünya'nın mavi görünmesinin nedeni budur." },
  { id: "p04-199", k: "Dünya", s: "Bir su molekülü atmosferde ortalama ne kadar kalır?", d: "Yaklaşık 9 gün", y: ["Yaklaşık 9 yıl", "Yaklaşık 9 saat"], a: "USGS'ye göre su buharı atmosferde ortalama yaklaşık dokuz gün kalır, sonra yağış olarak yere döner." },
  { id: "p04-200", k: "Dünya", s: "Buzullardan sonra en büyük tatlı su deposu hangisidir?", d: "Yeraltı suyu", y: ["Göller", "Nehirler"], a: "Sıvı tatlı suyun büyük kısmı yeraltındadır. Göller ve nehirlerdeki su bunun yanında çok küçük kalır." },
  { id: "p04-201", k: "Dünya", s: "Dünya'nın en büyük okyanusu hangisidir?", d: "Pasifik Okyanusu", y: ["Atlantik Okyanusu", "Hint Okyanusu"], a: "Pasifik, Dünya'daki bütün karaların toplam alanından daha geniştir." },
  { id: "p04-202", k: "Dünya", s: "Büyüklükte ikinci sıradaki okyanus hangisidir?", d: "Atlantik Okyanusu", y: ["Hint Okyanusu", "Güney Okyanusu"], a: "Atlantik, Avrupa ve Afrika'yı Amerika kıtalarından ayırır. Pasifik'ten sonra en büyük okyanustur." },
  { id: "p04-203", k: "Dünya", s: "En küçük okyanus hangisidir?", d: "Arktik Okyanusu", y: ["Hint Okyanusu", "Güney Okyanusu"], a: "Kuzey Buz Denizi olarak da bilinen Arktik Okyanusu en küçük ve en sığ okyanustur. Yüzeyinin büyük kısmı buzla kaplıdır." },
  { id: "p04-204", k: "Dünya", s: "Antarktika'yı çevreleyen okyanus hangisidir?", d: "Güney Okyanusu", y: ["Arktik Okyanusu", "Atlantik Okyanusu"], a: "Güney Okyanusu, Antarktika'nın çevresini dolaşan güçlü bir akıntıyla diğer okyanuslardan ayrılır." },
  { id: "p04-205", k: "Dünya", s: "Pasifik Okyanusu'na 'sakin' anlamına gelen adını veren denizci kimdir?", d: "Macellan", y: ["Kolomb", "James Cook"], a: "Macellan, fırtınalı bir boğazı geçtikten sonra karşılaştığı sakin sular yüzünden okyanusa Mar Pacifico adını verdi." },
  { id: "p04-206", k: "Dünya", s: "Okyanusların bilinen en derin noktası nerededir?", d: "Mariana Çukuru", y: ["Porto Riko Çukuru", "Kızıldeniz"], a: "Batı Pasifik'teki Mariana Çukuru'nun en derin yeri olan Challenger Derinliği yaklaşık 11 km derinliktedir." },
  { id: "p04-207", k: "Dünya", s: "Mariana Çukuru'nun en derin noktası yaklaşık kaç kilometre derinliktedir?", d: "Yaklaşık 11 km", y: ["Yaklaşık 3 km", "Yaklaşık 30 km"], a: "Challenger Derinliği yaklaşık 11 km'dir. Everest bu çukura yerleştirilseydi zirvesi suyun altında kalırdı." },
  { id: "p04-208", k: "Dünya", s: "Okyanusların ortalama derinliği yaklaşık ne kadardır?", d: "Yaklaşık 3,7 km", y: ["Yaklaşık 370 m", "Yaklaşık 37 km"], a: "NOAA'ya göre okyanusun ortalama derinliği yaklaşık 3.700 metredir." },
  { id: "p04-209", k: "Dünya", s: "Okyanus suyunun ortalama tuzluluğu yaklaşık ne kadardır?", d: "Litrede yaklaşık 35 gram", y: ["Litrede yaklaşık 3 gram", "Litrede yaklaşık 350 gram"], a: "Deniz suyunun her litresinde ortalama yaklaşık 35 gram çözünmüş tuz bulunur. Bu oran binde 35 olarak da ifade edilir." },
  { id: "p04-210", k: "Dünya", s: "Deniz suyundaki tuzun büyük kısmını hangi iki element oluşturur?", d: "Sodyum ve klor", y: ["Kalsiyum ve demir", "Potasyum ve kükürt"], a: "Deniz suyunda çözünmüş tuzların büyük kısmı, sofra tuzunu da oluşturan sodyum ve klor iyonlarıdır." },
  { id: "p04-211", k: "Dünya", s: "Okyanus tuzunun başlıca kaynaklarından biri nedir?", d: "Nehirlerin kayaçlardan çözüp taşıdığı mineraller", y: ["Yağmurun tuzlu olması", "Balıkların salgıları"], a: "Yağmur kayaçlardaki mineralleri çözer, nehirler bunları denize taşır. Su buharlaşır ama tuz denizde kalır." },
  { id: "p04-212", k: "Dünya", s: "Ölü Deniz'in bu kadar tuzlu olmasının nedeni nedir?", d: "Çıkışı yok ve suyu buharlaşıyor", y: ["Okyanusa bağlı olması", "Çok yağış alması"], a: "Ölü Deniz'e gelen su yalnızca buharlaşarak ayrılır. Tuz geride kalır ve birikir." },
  { id: "p04-213", k: "Dünya", s: "Kıtalarda kuru yüzeydeki en alçak nokta hangi gölün kıyısındadır?", d: "Ölü Deniz", y: ["Hazar Denizi", "Van Gölü"], a: "Ölü Deniz'in kıyısı deniz seviyesinin 400 metreden fazla altındadır ve karadaki en alçak yer kabul edilir." },
  { id: "p04-214", k: "Dünya", s: "Ölü Deniz'de insanlar neden kolayca yüzeyde kalır?", d: "Çok tuzlu suyun kaldırma kuvveti yüksektir", y: ["Su çok sıcaktır", "Hiç dalga yoktur"], a: "Tuz suyun yoğunluğunu artırır. Yoğun su insan vücudunu daha güçlü yukarı iter." },
  { id: "p04-215", k: "Dünya", s: "Yüz ölçümü bakımından dünyanın en büyük gölü hangisidir?", d: "Hazar Denizi", y: ["Superior Gölü", "Baykal Gölü"], a: "Hazar Denizi adına rağmen karayla çevrili bir göldür. Suyu hafif tuzludur." },
  { id: "p04-216", k: "Dünya", s: "Hazar Denizi'nin okyanusa doğal bir çıkışı var mıdır?", d: "Yoktur", y: ["Karadeniz üzerinden vardır", "Basra Körfezi üzerinden vardır"], a: "Hazar kapalı bir havzadır. Volga gibi nehirlerden gelen su yalnızca buharlaşarak ayrılır." },
  { id: "p04-217", k: "Dünya", s: "Dünyanın en derin gölü hangisidir?", d: "Baykal Gölü", y: ["Tanganika Gölü", "Van Gölü"], a: "Sibirya'daki Baykal Gölü 1.600 metreyi aşan derinliğiyle dünyanın en derin gölüdür." },
  { id: "p04-218", k: "Dünya", s: "Baykal Gölü, dünyadaki donmamış yüzey tatlı suyunun yaklaşık ne kadarını barındırır?", d: "Yaklaşık beşte birini", y: ["Yaklaşık %1'ini", "Yaklaşık yarısını"], a: "Baykal o kadar derindir ki tek başına dünyadaki sıvı yüzey tatlı suyunun yaklaşık beşte birini içerir." },
  { id: "p04-219", k: "Dünya", s: "Yüzey alanı bakımından en büyük tatlı su gölü hangisidir?", d: "Superior Gölü", y: ["Baykal Gölü", "Victoria Gölü"], a: "ABD ile Kanada arasındaki Superior, alan bakımından en büyük tatlı su gölüdür. Hacimde ise Baykal öndedir." },
  { id: "p04-220", k: "Dünya", s: "Kuzey Amerika'daki Büyük Göller kaç gölden oluşur?", d: "5", y: ["3", "7"], a: "Superior, Michigan, Huron, Erie ve Ontario gölleri birbirine bağlıdır ve dev bir tatlı su sistemi oluşturur." },
  { id: "p04-221", k: "Dünya", s: "Afrika'nın en büyük gölü hangisidir?", d: "Victoria Gölü", y: ["Tanganika Gölü", "Çad Gölü"], a: "Victoria Gölü Uganda, Kenya ve Tanzanya arasında paylaşılır. Beyaz Nil bu gölden çıkar." },
  { id: "p04-222", k: "Dünya", s: "Türkiye'nin en büyük gölü hangisidir?", d: "Van Gölü", y: ["Tuz Gölü", "Beyşehir Gölü"], a: "Van Gölü Türkiye'nin hem en büyük hem de en derin gölüdür. Suyu sodalı ve tuzludur." },
  { id: "p04-223", k: "Dünya", s: "Van Gölü'nün suyu hangi özelliğiyle bilinir?", d: "Sodalı ve tuzlu olması", y: ["Çok tatlı olması", "Sıcak kaynak olması"], a: "Van Gölü'nün suyu sodalıdır. Bu sert koşullara uyum sağlayan inci kefali gölde yaşayabilen az sayıdaki balıktandır." },
  { id: "p04-224", k: "Dünya", s: "Türkiye'nin en büyük tatlı su gölü hangisidir?", d: "Beyşehir Gölü", y: ["Van Gölü", "Tuz Gölü"], a: "Van Gölü daha büyük olsa da suyu sodalıdır. Konya ve Isparta'daki Beyşehir Gölü en büyük tatlı su gölümüzdür." },
  { id: "p04-225", k: "Dünya", s: "Türkiye'de sofra tuzunun önemli bir kısmının üretildiği göl hangisidir?", d: "Tuz Gölü", y: ["Van Gölü", "Eğirdir Gölü"], a: "Tuz Gölü çok sığdır. Yazın suyu büyük ölçüde buharlaşır ve geride kalın bir tuz tabakası bırakır." },
  { id: "p04-226", k: "Dünya", s: "Kanada ve Finlandiya'daki binlerce gölün çoğu nasıl oluşmuştur?", d: "Buzulların aşındırmasıyla", y: ["Göktaşı çarpmalarıyla", "Volkan kraterlerinde"], a: "Buzul çağlarında kalın buz örtüleri araziyi kazıdı. Buzlar çekilince oluşan çukurlar suyla doldu." },
  { id: "p04-227", k: "Dünya", s: "Heyelan ya da birikintilerin bir vadinin önünü kapatmasıyla oluşan göle ne denir?", d: "Set gölü", y: ["Krater gölü", "Lagün"], a: "Doğal bir set akarsuyun yolunu kapatınca su arkasında birikir ve set gölü oluşur." },
  { id: "p04-228", k: "Dünya", s: "Kıyıda kum setiyle denizden ayrılmış sığ göllere ne ad verilir?", d: "Lagün", y: ["Fiyort", "Delta"], a: "Lagünler kıyı akıntılarının taşıdığı kumun bir koyun ağzını kapatmasıyla oluşur. Köyceğiz Gölü bunun bilinen bir örneğidir." },
  { id: "p04-229", k: "Dünya", s: "Buzulların oyduğu, denizin içine girdiği dik yamaçlı derin koylara ne ad verilir?", d: "Fiyort", y: ["Lagün", "Delta"], a: "Fiyortlar buzul vadilerinin deniz seviyesinin altında kalan bölümleridir. Kıyıdan çok içerilere uzanabilir." },
  { id: "p04-230", k: "Dünya", s: "Fiyortlarıyla ünlü Avrupa ülkesi hangisidir?", d: "Norveç", y: ["Hollanda", "Portekiz"], a: "Norveç'in batı kıyısı buzul çağında oyulmuş yüzlerce fiyortla kaplıdır." },
  { id: "p04-231", k: "Dünya", s: "Akarsuyun taşıdığı alüvyonların denize döküldüğü yerde birikmesiyle oluşan düzlüğe ne denir?", d: "Delta", y: ["Haliç", "Kanyon"], a: "Nil ve Göksu gibi akarsuların ağzındaki deltalar verimli tarım alanlarıdır." },
  { id: "p04-232", k: "Dünya", s: "Akarsuyun düz bir arazide kıvrıla kıvrıla akmasına ne ad verilir?", d: "Menderes", y: ["Şelale", "Delta"], a: "Bu ad, Batı Anadolu'daki Büyük Menderes Nehri'nin (antik adı Maiandros) kıvrımlı akışından gelir." },
  { id: "p04-233", k: "Dünya", s: "Akarsuların taşıyıp düzlüklerde biriktirdiği ince ve verimli tortulara ne denir?", d: "Alüvyon", y: ["Moren", "Kumul"], a: "Alüvyonlu topraklar çok verimlidir. Bu yüzden büyük uygarlıklar sıklıkla nehir boylarında kurulmuştur." },
  { id: "p04-234", k: "Dünya", s: "Dünyanın en çok su taşıyan nehri hangisidir?", d: "Amazon", y: ["Nil", "Mississippi"], a: "Amazon, okyanuslara ulaşan nehir suyunun yaklaşık beşte birini tek başına taşır." },
  { id: "p04-235", k: "Dünya", s: "Nil Nehri hangi denize dökülür?", d: "Akdeniz", y: ["Kızıldeniz", "Arap Denizi"], a: "Nil kuzeye doğru akar ve Mısır'da geniş bir delta oluşturarak Akdeniz'e dökülür." },
  { id: "p04-236", k: "Dünya", s: "Nil'in Sudan'ın başkenti Hartum'da birleşen iki ana kolu hangileridir?", d: "Beyaz Nil ve Mavi Nil", y: ["Kızıl Nil ve Yeşil Nil", "Kara Nil ve Sarı Nil"], a: "Beyaz Nil Victoria Gölü yönünden, Mavi Nil ise Etiyopya'dan gelir. İkisi Hartum'da birleşir." },
  { id: "p04-237", k: "Dünya", s: "Mavi Nil hangi gölden çıkar?", d: "Tana Gölü", y: ["Victoria Gölü", "Çad Gölü"], a: "Mavi Nil Etiyopya'daki Tana Gölü'nden çıkar. Nil'in yaz taşkınlarının büyük kısmını bu kol taşır." },
  { id: "p04-238", k: "Dünya", s: "Mısır'da Nil üzerine kurulan Asvan Barajı'nın arkasında oluşan göl hangisidir?", d: "Nasır Gölü", y: ["Tana Gölü", "Victoria Gölü"], a: "Asvan Barajı 1970'te tamamlandı. Arkasında oluşan Nasır Gölü dünyanın en büyük yapay göllerindendir." },
  { id: "p04-239", k: "Dünya", s: "Avrupa'nın en uzun nehri hangisidir?", d: "Volga", y: ["Tuna", "Ren"], a: "Volga Rusya'da akar ve Hazar Denizi'ne dökülür. Avrupa'nın en uzun nehridir." },
  { id: "p04-240", k: "Dünya", s: "Dünyada en fazla ülkeden geçen ya da sınır oluşturan nehir hangisidir?", d: "Tuna", y: ["Volga", "Ren"], a: "Tuna, Almanya'dan Karadeniz'e kadar 10 ülkeden geçer ya da sınırlarını çizer." },
  { id: "p04-241", k: "Dünya", s: "Tuna Nehri hangi denize dökülür?", d: "Karadeniz", y: ["Akdeniz", "Baltık Denizi"], a: "Tuna, Romanya ile Ukrayna sınırında geniş bir delta oluşturarak Karadeniz'e dökülür." },
  { id: "p04-242", k: "Dünya", s: "Ren Nehri hangi denize dökülür?", d: "Kuzey Denizi", y: ["Baltık Denizi", "Akdeniz"], a: "Ren, İsviçre Alpleri'nden doğar ve Hollanda'dan Kuzey Denizi'ne dökülür." },
  { id: "p04-243", k: "Dünya", s: "Volga Nehri nereye dökülür?", d: "Hazar Denizi", y: ["Karadeniz", "Baltık Denizi"], a: "Volga, Hazar Denizi'ne su sağlayan en büyük nehirdir." },
  { id: "p04-244", k: "Dünya", s: "Kaynağı da ağzı da Türkiye sınırları içinde olan en uzun nehir hangisidir?", d: "Kızılırmak", y: ["Sakarya", "Yeşilırmak"], a: "Kızılırmak Sivas'tan doğar, yay çizerek akar ve Bafra'da Karadeniz'e dökülür." },
  { id: "p04-245", k: "Dünya", s: "Fırat ve Dicle nehirleri hangi ülkede doğar?", d: "Türkiye", y: ["İran", "Suriye"], a: "İki nehir de Doğu Anadolu'nun dağlarından doğar, güneye akarak Mezopotamya ovalarını sular." },
  { id: "p04-246", k: "Dünya", s: "Fırat ve Dicle birleşerek hangi su yolunu oluşturur?", d: "Şattülarap", y: ["Süveyş", "Hürmüz"], a: "Fırat ve Dicle Irak'ta birleşir. Şattülarap adını alan nehir Basra Körfezi'ne dökülür." },
  { id: "p04-247", k: "Dünya", s: "Türkiye'nin en büyük barajlarından Atatürk Barajı hangi nehir üzerindedir?", d: "Fırat", y: ["Dicle", "Kızılırmak"], a: "Atatürk Barajı Fırat üzerinde kuruludur ve Güneydoğu Anadolu Projesi'nin temel yapısıdır." },
  { id: "p04-248", k: "Dünya", s: "Meriç Nehri hangi denize dökülür?", d: "Ege Denizi", y: ["Karadeniz", "Marmara Denizi"], a: "Meriç, Bulgaristan'dan doğar, Türkiye-Yunanistan sınırını çizer ve Ege Denizi'ne dökülür." },
  { id: "p04-249", k: "Dünya", s: "Asya'nın en uzun nehri hangisidir?", d: "Yangtze (Çang Jiang)", y: ["Ganj", "Mekong"], a: "Çin'deki Yangtze, Asya'nın en uzun nehridir ve Doğu Çin Denizi'ne dökülür." },
  { id: "p04-250", k: "Dünya", s: "Ganj Nehri hangi körfeze dökülür?", d: "Bengal Körfezi", y: ["Basra Körfezi", "Aden Körfezi"], a: "Ganj, Brahmaputra ile birlikte Bengal Körfezi'ne dökülür ve dünyanın en büyük deltalarından birini oluşturur." },
  { id: "p04-251", k: "Dünya", s: "Ekvatoru iki kez kesen büyük Afrika nehri hangisidir?", d: "Kongo", y: ["Nil", "Nijer"], a: "Kongo Nehri yay çizerek akar ve ekvatoru iki kez keser. Bu yüzden havzasının bir kısmı her mevsim yağış alır." },
  { id: "p04-252", k: "Dünya", s: "Victoria Şelalesi hangi nehir üzerindedir?", d: "Zambezi", y: ["Nil", "Kongo"], a: "Zambiya ile Zimbabve sınırındaki Victoria Şelalesi, Zambezi Nehri'nin geniş bir yarığa dökülmesiyle oluşur." },
  { id: "p04-253", k: "Dünya", s: "Kesintisiz düşüşüyle dünyanın en yüksek şelalesi hangisidir?", d: "Angel Şelalesi", y: ["Niagara Şelalesi", "Victoria Şelalesi"], a: "Venezuela'daki Angel Şelalesi yaklaşık 979 metre yükseklikten düşer. En uzun kesintisiz düşüşü yaklaşık 800 metredir." },
  { id: "p04-254", k: "Dünya", s: "Niagara Şelalesi hangi iki ülkenin sınırındadır?", d: "ABD ve Kanada", y: ["ABD ve Meksika", "Kanada ve Grönland"], a: "Niagara Şelalesi Erie ile Ontario göllerini bağlayan Niagara Nehri üzerindedir." },
  { id: "p04-255", k: "Dünya", s: "İguazu Şelaleleri hangi iki ülkenin sınırındadır?", d: "Arjantin ve Brezilya", y: ["Peru ve Şili", "Kolombiya ve Venezuela"], a: "İguazu, yüzlerce ayrı çağlayandan oluşan geniş bir şelale sistemidir." },
  { id: "p04-256", k: "Dünya", s: "ABD'deki Büyük Kanyon'u hangi nehir oymuştur?", d: "Colorado", y: ["Mississippi", "Missouri"], a: "Colorado Nehri milyonlarca yıl boyunca kayaları aşındırarak yaklaşık 1,8 km derinliğe ulaşan kanyonu oydu." },
  { id: "p04-257", k: "Dünya", s: "Bir nehrin ve kollarının yağış suyunu topladığı alanın tamamına ne ad verilir?", d: "Akarsu havzası", y: ["Delta", "Akifer"], a: "Bir havzaya düşen yağış aynı ana nehre ve sonunda aynı denize ya da göle ulaşır." },
  { id: "p04-258", k: "Dünya", s: "Komşu iki akarsu havzasını birbirinden ayıran en yüksek çizgiye ne denir?", d: "Su bölümü çizgisi", y: ["Kıyı çizgisi", "İzobar"], a: "Su bölümü çizgisinin bir tarafına düşen yağış bir havzaya, diğer tarafına düşen yağış öteki havzaya akar." },
  { id: "p04-259", k: "Dünya", s: "Suları okyanusa ulaşmayan, iç kesimde göl ya da çölde son bulan havzaya ne denir?", d: "Kapalı havza", y: ["Açık havza", "Delta havzası"], a: "Kapalı havzalarda su buharlaşarak ayrılır. Hazar, Van Gölü ve Konya Ovası bu tür havzalara örnektir." },
  { id: "p04-260", k: "Dünya", s: "Bir nehrin denize ulaştığı yerde gelgit ve deniz suyuyla genişlemiş huni biçimli ağzına ne denir?", d: "Haliç", y: ["Delta", "Menderes"], a: "Haliçlerde tatlı su ile tuzlu su karışır. Thames ve St. Lawrence nehirlerinin ağızları bu türdendir." },
  { id: "p04-261", k: "Dünya", s: "Sıcak yolda uzakta su birikintisi varmış gibi görünmesine ne denir?", d: "Serap", y: ["Hale", "Gökkuşağı"], a: "Yere yakın sıcak hava ışığı büker. Gördüğümüz parlak 'su', aslında gökyüzünün yansımasıdır." },
  { id: "p04-262", k: "Dünya", s: "Bataklık ve sulak alanlar su döngüsünde hangi önemli işlevi görür?", d: "Suyu sünger gibi tutup taşkınları azaltır", y: ["Suyu tuzlandırır", "Buharlaşmayı tamamen durdurur"], a: "Sulak alanlar fazla suyu emer, yavaşça bırakır ve yeraltı suyunu besler. Aynı zamanda suyu doğal olarak süzer." },
  { id: "p04-263", k: "Dünya", s: "Sulak alanların korunması için 1971'de İran'da imzalanan uluslararası sözleşme hangisidir?", d: "Ramsar Sözleşmesi", y: ["Kyoto Protokolü", "Montreal Protokolü"], a: "Ramsar Sözleşmesi, imzalandığı İran kentinin adını taşır. Türkiye'de de birçok Ramsar alanı vardır." },
  { id: "p04-264", k: "Dünya", s: "Basınç nedeniyle suyun pompasız olarak kendiliğinden yüzeye çıktığı kuyuya ne ad verilir?", d: "Artezyen kuyusu", y: ["Sarnıç", "Su kemeri"], a: "Artezyen kuyusunda su, iki geçirimsiz katman arasında basınç altında tutulur. Kuyu açılınca su kendiliğinden yükselir." },
  { id: "p04-265", k: "Dünya", s: "Okyanus yüzey akıntılarını harekete geçiren ana etken nedir?", d: "Rüzgâr", y: ["Ay ışığı", "Deniz tabanındaki volkanlar"], a: "Hâkim rüzgârlar yüzey suyunu sürükler. Kıtalar ve Coriolis etkisi bu akıntıların yönünü biçimlendirir." },
  { id: "p04-266", k: "Dünya", s: "Derin okyanus dolaşımını büyük ölçüde ne sürdürür?", d: "Sıcaklık ve tuzluluk farkları", y: ["Gemi trafiği", "Dünya'nın manyetik alanı"], a: "Soğuk ve tuzlu su daha yoğundur ve dibe çöker. Bu yoğunluk farkları okyanusları birbirine bağlayan yavaş bir dolaşım oluşturur." },
  { id: "p04-267", k: "Dünya", s: "Sıcaklık ve tuzluluk farklarıyla süren küresel okyanus dolaşımına ne ad verilir?", d: "Termohalin dolaşım", y: ["Hadley dolaşımı", "Muson dolaşımı"], a: "Termo sıcaklık, halin ise tuz anlamına gelir. Bu dolaşıma küresel taşıma bandı da denir." },
  { id: "p04-268", k: "Dünya", s: "Termohalin dolaşımda soğuk ve tuzlu suyun dibe çöktüğü başlıca bölgeler hangileridir?", d: "Kuzey Atlantik ve Antarktika çevresi", y: ["Ekvator Pasifiği", "Hint Okyanusu'nun ortası"], a: "Bu bölgelerde soğuyan ve donan deniz suyu tuzlanıp ağırlaşır, okyanus tabanına doğru çöker." },
  { id: "p04-269", k: "Dünya", s: "Batı Avrupa'nın kışlarını benzer enlemdeki yerlere göre daha ılık yapan sıcak akıntı hangisidir?", d: "Gulf Stream (Golfstrim)", y: ["Labrador Akıntısı", "Kanarya Akıntısı"], a: "Gulf Stream ve devamı olan Kuzey Atlantik Akıntısı tropiklerden kuzeye sıcak su taşır." },
  { id: "p04-270", k: "Dünya", s: "Gulf Stream akıntısını ilk ayrıntılı haritalayanlardan olan Amerikalı devlet adamı kimdir?", d: "Benjamin Franklin", y: ["Thomas Jefferson", "George Washington"], a: "Franklin posta müdürüyken gemi kaptanlarından bilgi topladı ve 18. yüzyılda Gulf Stream haritasını yayımladı." },
  { id: "p04-271", k: "Dünya", s: "Japonya'nın doğu kıyıları boyunca kuzeye akan sıcak akıntı hangisidir?", d: "Kuroşio", y: ["Oyaşio", "Humboldt"], a: "Kuroşio, Pasifik'in Gulf Stream'e benzeyen güçlü sıcak akıntısıdır. Adı Japoncada kara akıntı anlamına gelir." },
  { id: "p04-272", k: "Dünya", s: "Kanada'nın doğusunda kuzeyden güneye akan soğuk akıntı hangisidir?", d: "Labrador Akıntısı", y: ["Gulf Stream", "Kuroşio"], a: "Labrador Akıntısı Arktik'ten soğuk su ve buzdağları taşır." },
  { id: "p04-273", k: "Dünya", s: "Labrador Akıntısı ile Gulf Stream'in buluştuğu Newfoundland açıklarında hangi olay çok sık görülür?", d: "Yoğun sis", y: ["Tropikal kasırga", "Kum fırtınası"], a: "Sıcak akıntının nemli havası soğuk akıntının üzerinden geçince soğur ve yoğun sis oluşur." },
  { id: "p04-274", k: "Dünya", s: "Soğuk okyanus akıntılarının geçtiği kıyılar genellikle nasıldır?", d: "Kurak", y: ["Çok yağışlı", "Çok sıcak"], a: "Soğuk su üstündeki havayı soğutur ve havanın yükselmesini engeller. Bu yüzden Atacama ve Namib gibi kıyı çölleri oluşur." },
  { id: "p04-275", k: "Dünya", s: "Peru ve Şili açıklarının balıkça çok zengin olmasının temel nedeni nedir?", d: "Derinden besince zengin su yükselmesi", y: ["Suyun çok sıcak olması", "Tuzluluğun çok düşük olması"], a: "Rüzgârlar yüzey suyunu açığa iter, yerine derinden besin yüklü soğuk su gelir. Bu su planktonları ve balıkları besler." },
  { id: "p04-276", k: "Dünya", s: "Güney Amerika'nın batı kıyısı boyunca kuzeye akan soğuk akıntı hangisidir?", d: "Humboldt (Peru) Akıntısı", y: ["Brezilya Akıntısı", "Gulf Stream"], a: "Humboldt Akıntısı Antarktika yönünden soğuk su taşır. Atacama Çölü'nün kuraklığında da payı vardır." },
  { id: "p04-277", k: "Dünya", s: "Afrika'nın güneybatı kıyısında kuzeye akan, Namib Çölü'nün kuraklığına katkıda bulunan soğuk akıntı hangisidir?", d: "Benguela Akıntısı", y: ["Agulhas Akıntısı", "Gulf Stream"], a: "Benguela Akıntısı'nın soğuk suyu kıyıda yağışı engeller, ama sık sis oluşturur." },
  { id: "p04-278", k: "Dünya", s: "El Niño nedir?", d: "Doğu ve orta tropikal Pasifik'in olağandışı ısınması", y: ["Atlantik'te bir kasırga türü", "Hint Okyanusu'nun soğuması"], a: "El Niño sırasında tropikal Pasifik'teki sıcak su doğuya kayar ve dünya genelinde hava düzenlerini etkiler." },
  { id: "p04-279", k: "Dünya", s: "İspanyolca 'El Niño' adı ne anlama gelir?", d: "Erkek çocuk", y: ["Sıcak rüzgâr", "Küçük deniz"], a: "Perulu balıkçılar bu ısınmayı genellikle Noel'e yakın fark ettikleri için olaya Çocuk İsa'yı anan bu adı verdiler." },
  { id: "p04-280", k: "Dünya", s: "El Niño'nun tersi olan, tropikal Pasifik'in olağandışı soğuması hangi adla bilinir?", d: "La Niña", y: ["El Nido", "La Brisa"], a: "La Niña İspanyolcada kız çocuk demektir. El Niño ile birlikte ENSO adı verilen döngünün iki ucunu oluşturur." },
  { id: "p04-281", k: "Dünya", s: "El Niño dönemlerinde Peru açıklarındaki balıkçılık genellikle nasıl etkilenir?", d: "Azalır", y: ["Artar", "Değişmez"], a: "Isınan yüzey suyu derinden besin yüklü suyun yükselmesini zayıflatır. Plankton ve balık sayısı düşer." },
  { id: "p04-282", k: "Dünya", s: "El Niño olayları genellikle ne sıklıkla görülür?", d: "Birkaç yılda bir", y: ["Her yıl", "Yüzyılda bir"], a: "El Niño düzensiz aralıklarla, genellikle 2 ila 7 yılda bir ortaya çıkar." },
  { id: "p04-283", k: "Dünya", s: "Kuzey Atlantik'te akıntılarla çevrili, hiçbir kara kıyısı olmayan deniz hangisidir?", d: "Sargasso Denizi", y: ["Kuzey Denizi", "Baltık Denizi"], a: "Sargasso Denizi'nin sınırlarını kıyılar değil, onu çevreleyen akıntılar belirler. Yüzeyinde yüzen sargassum yosunları bulunur." },
  { id: "p04-284", k: "Dünya", s: "Okyanuslarda kıtaların arasında dönen dev dairesel akıntı sistemlerine ne ad verilir?", d: "Okyanus girdabı", y: ["Termoklin", "Haliç"], a: "Büyük okyanus girdapları rüzgârlar ve Coriolis etkisiyle oluşur. Kuzey yarımkürede saat yönünde döner." },
  { id: "p04-285", k: "Dünya", s: "Kuzey Pasifik'te yüzen plastik atıkların yoğun biriktiği bölge hangi adla bilinir?", d: "Büyük Pasifik Çöp Alanı", y: ["Mariana Atık Çukuru", "Bermuda Üçgeni"], a: "Akıntılar plastikleri girdabın ortasında toplar. Atıkların çoğu yüzer ada değil, sudaki küçük plastik parçalardır." },
  { id: "p04-286", k: "Dünya", s: "Dünyanın en çok su taşıyan okyanus akıntısı hangisidir?", d: "Antarktika Çevresel Akıntısı", y: ["Gulf Stream", "Kuroşio"], a: "Antarktika'yı batıdan doğuya dolanan bu akıntı, kıtalarla kesilmediği için bütün okyanusları birbirine bağlar." },
  { id: "p04-287", k: "Dünya", s: "Hint Okyanusu'nun kuzeyinde yüzey akıntıları neden mevsime göre yön değiştirir?", d: "Muson rüzgârları yön değiştirdiği için", y: ["Gelgitler yön değiştirdiği için", "Buzdağları eridiği için"], a: "Yazın ve kışın ters yönde esen muson rüzgârları, kuzey Hint Okyanusu'nda akıntıların da yönünü çevirir." },
];
